INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(1,2,1,'2026-04-12','Fluctuating','["Mức tập trung 1/5 đi kèm với 1 lần mất tập trung trong 1 giờ học","Yếu tố gây mất tập trung xuất hiện 1 lần trong phiên học 1 giờ"]','Nếu Yếu tố gây mất tập trung xuất hiện 1 lần trong phiên học 1 giờ không thay đổi, mức tập trung 1/5 có khả năng duy trì ở mức thấp trong phiên tiếp theo. Nếu loại bỏ hoàn toàn yếu tố gây mất tập trung, mức tập trung có khả năng cải thiện lên mức 2/5.','Tín hiệu Yếu tố gây mất tập trung xuất hiện 1 lần trong phiên học 1 giờ cho thấy đây là nguyên nhân trực tiếp làm giảm mức tập trung xuống 1/5, vì sự xuất hiện của yếu tố này trùng khớp với thời điểm ghi nhận mức tập trung thấp nhất.','Để xử lý Yếu tố gây mất tập trung xuất hiện 1 lần trong phiên học 1 giờ, cần thiết lập rào cản vật lý ngăn chặn yếu tố này tiếp cận không gian học tập trong suốt thời gian phiên học.','["Di chuyển thiết bị hoặc vật dụng gây mất tập trung ra khỏi khu vực học tập trước khi bắt đầu phiên học tiếp theo trong 48 giờ tới.","Thiết lập không gian học tập trống hoàn toàn các vật dụng không liên quan để kiểm soát yếu tố gây mất tập trung.","Đo lại mức tập trung trong phiên tiếp theo, mục tiêu đạt mức 2/5 để xác nhận hiệu quả của việc loại bỏ yếu tố gây mất tập trung."]','Nếu mức tập trung đạt 2/5 trong phiên tiếp theo thì duy trì quy trình kiểm soát môi trường; nếu mức tập trung vẫn ở 1/5 thì thực hiện rà soát lại danh mục các yếu tố gây mất tập trung tiềm ẩn khác.','','2026-04-12 10:08:35',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(2,2,4,'2026-04-12','Fluctuating','["Mức tập trung tăng từ 1/5 lên 2/5 trong khi số giờ học duy trì ổn định ở mức 1 giờ.","Mức muốn bỏ cuộc tăng từ 1/5 lên 3/5 trong khi mục tiêu học tập vẫn được hoàn thành."]','Nếu mức muốn bỏ cuộc tăng từ 1/5 lên 3/5 không thay đổi, tín hiệu mức tập trung 2/5 có khả năng giảm xuống mức 1/5 trong phiên tiếp theo. Nếu thời gian học mỗi phiên được chia nhỏ thành các block 20 phút, mức muốn bỏ cuộc có khả năng cải thiện về mức 1/5.','Tín hiệu mức muốn bỏ cuộc tăng từ 1/5 lên 3/5 cho thấy đây là nguyên nhân gốc rễ, vì dù mục tiêu vẫn đạt nhưng xu hướng tâm lý muốn dừng lại đang gia tăng nhanh chóng, tạo ra sự mâu thuẫn với hiệu suất học tập.','Để xử lý mức muốn bỏ cuộc tăng từ 1/5 lên 3/5, cần áp dụng cơ chế chia nhỏ khối lượng công việc thành các đơn vị thời gian ngắn hơn để giảm áp lực tâm lý trong mỗi phiên học.','["Chia nhỏ 1 giờ học thành 3 block, mỗi block 20 phút, nghỉ giải lao 5 phút giữa các block trong phiên tiếp theo.","Thiết lập bộ đếm thời gian 20 phút cho mỗi block để kiểm soát thời gian học tập tập trung.","Đo lại mức muốn bỏ cuộc vào cuối phiên tiếp theo, mục tiêu cần đạt là mức 1/5 hoặc 2/5."]','Nếu mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì thực hiện giảm thời gian học xuống còn 45 phút; nếu mức tập trung đạt 3/5 thì duy trì cấu trúc chia nhỏ thời gian học.','','2026-04-12 12:46:46',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(3,2,6,'2026-04-12','Stable','["Mức tập trung tăng từ 1/5 ở phiên 1 lên 5/5 ở phiên 3, đồng thời số giờ học tăng từ 1h lên 4h.","Mức muốn bỏ cuộc biến động từ 1/5 ở phiên 1 lên 3/5 ở phiên 2 và giảm về 1/5 ở phiên 3."]','Nếu mức muốn bỏ cuộc không ổn định, tín hiệu mức tập trung 5/5 có khả năng giảm xuống mức 2/5 như đã ghi nhận ở phiên 2. Nếu duy trì thời lượng học 4h ổn định, mức muốn bỏ cuộc có khả năng duy trì ở mức 1/5.','Tín hiệu mức muốn bỏ cuộc biến động từ 1/5 lên 3/5 rồi về 1/5 cho thấy sự thiếu ổn định trong tâm thế duy trì cường độ học tập cao.','Để xử lý mức muốn bỏ cuộc biến động, cần thiết lập cơ chế phân bổ khối lượng học tập theo chu kỳ để tránh quá tải dẫn đến ý định bỏ cuộc.','["Chia nhỏ 4h học thành 4 block 60 phút với 10 phút nghỉ giữa mỗi block trong phiên tiếp theo.","Ghi chép lại mức muốn bỏ cuộc ngay sau khi kết thúc mỗi block 60 phút để kiểm soát biến động.","Đo lại mức muốn bỏ cuộc ở phiên tiếp theo, mục tiêu đạt mức 1/5 hoặc 2/5."]','Nếu mức muốn bỏ cuộc đạt 3/5 trong phiên tiếp theo thì giảm thời lượng học xuống 2h; nếu mức tập trung giảm xuống dưới 3/5 thì thực hiện nghỉ giải lao 15 phút.','','2026-04-12 12:51:17',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(4,2,7,'2026-04-12','High Risk','["Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại trong khi số giờ học giảm từ 4h xuống 2h.","Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 ở phiên hiện tại đi kèm với kết quả không đạt mục tiêu học tập."]','Nếu mức muốn bỏ cuộc 4/5 không thay đổi, tín hiệu mức tập trung 3/5 có khả năng tiếp tục giảm xuống dưới 3/5 trong phiên tiếp theo. Nếu thời gian học được điều chỉnh giảm xuống 1h, mức muốn bỏ cuộc có khả năng cải thiện về mức 2/5.','Tín hiệu mức muốn bỏ cuộc tăng từ 1/5 lên 4/5 cho thấy sự sụt giảm động lực nội tại là nguyên nhân gốc rễ dẫn đến việc không đạt mục tiêu và giảm thời gian học.','Để xử lý mức muốn bỏ cuộc 4/5, cần áp dụng cơ chế chia nhỏ khối lượng kiến thức thành các đơn vị học tập ngắn hạn để giảm áp lực hoàn thành mục tiêu trong một phiên.','["Giảm thời gian học bắt buộc xuống còn 1h mỗi phiên trong 48h tới để giảm áp lực hoàn thành mục tiêu.","Chia nhỏ nội dung học thành 2 phần, mỗi phần 30 phút với thời gian nghỉ giữa giờ cố định để kiểm soát mức muốn bỏ cuộc.","Đo lại mức muốn bỏ cuộc vào cuối phiên tiếp theo, chỉ số cần đạt là 2/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì thực hiện giảm thời gian học xuống 0.5h; nếu mức tập trung đạt 4/5 thì duy trì thời gian học 1h.','','2026-04-12 12:52:22',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(5,7,11,'2026-04-12','Fluctuating','["Mức tập trung giảm từ 5/5 xuống 3/5 trong khi số giờ học duy trì ổn định ở mức 3 giờ mỗi phiên.","Mức muốn bỏ cuộc tăng từ 1/5 lên 2/5 tương ứng với sự sụt giảm của mức tập trung qua 2 phiên."]','Nếu mức tập trung giảm từ 5/5 xuống 3/5 không thay đổi, mức muốn bỏ cuộc có khả năng tiếp tục tăng vượt ngưỡng 2/5. Nếu thời gian nghỉ giải lao giữa giờ được điều chỉnh, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 3/5 cho thấy sự suy giảm khả năng duy trì cường độ học tập, đây là nguyên nhân gốc dẫn đến việc tăng mức muốn bỏ cuộc.','Để xử lý mức tập trung giảm từ 5/5 xuống 3/5, cần áp dụng cơ chế chia nhỏ khối lượng kiến thức thành các phân đoạn 45 phút kèm nghỉ giải lao chủ động để giảm tải áp lực nhận thức.','["Chia nhỏ 3 giờ học thành 4 phân đoạn 45 phút, thực hiện trong phiên học tiếp theo để giảm tải áp lực nhận thức.","Thiết lập thời gian nghỉ giải lao 5 phút sau mỗi phân đoạn 45 phút để kiểm soát sự sụt giảm mức tập trung.","Đo lại mức tập trung vào cuối phiên tiếp theo, mục tiêu đạt mức 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt dưới 3/5 trong phiên tiếp theo thì thực hiện giảm thời gian học xuống 2 giờ; nếu mức muốn bỏ cuộc đạt 3/5 thì thực hiện tạm dừng học trong 24 giờ.','','2026-04-12 12:56:51',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(6,11,19,'2026-04-12','Fluctuating','["Mức tập trung 3/5 đi kèm với mật độ mất tập trung 50.00 lần/giờ trong 2 giờ học.","Mức muốn bỏ cuộc 1/5 xuất hiện đồng thời với trạng thái mệt mỏi sau 2 giờ học."]','Nếu mật độ mất tập trung 50.00 lần/giờ không thay đổi, mức tập trung 3/5 có khả năng giảm xuống dưới 3/5 trong phiên tiếp theo. Nếu thời gian học được chia nhỏ thành các block 30 phút, mật độ mất tập trung có khả năng giảm xuống dưới 25 lần/giờ.','Tín hiệu mật độ mất tập trung 50.00 lần/giờ cho thấy sự phân tán nguồn lực nhận thức là nguyên nhân gốc dẫn đến trạng thái mệt mỏi sau 2 giờ học.','Để xử lý mật độ mất tập trung 50.00 lần/giờ, áp dụng cơ chế chia nhỏ thời gian học thành các block 30 phút kèm 5 phút nghỉ để giảm tải nhận thức.','["Chia nhỏ phiên học 2 giờ thành 4 block, mỗi block 30 phút, thực hiện ngay trong phiên tiếp theo.","Thiết lập môi trường học tập không thiết bị điện tử không liên quan trong mỗi block 30 phút để kiểm soát mật độ mất tập trung.","Đo lại mật độ mất tập trung trong phiên tiếp theo, mục tiêu đạt dưới 25 lần/giờ để xác nhận hiệu quả."]','Nếu mật độ mất tập trung đạt trên 40 lần/giờ trong phiên tiếp theo thì thực hiện giảm thời gian mỗi block xuống còn 20 phút. Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 30 phút.','','2026-04-12 14:56:35',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(7,14,27,'2026-04-13','Stable','["Mức tập trung 3/5 đạt được trong thời gian học 1 giờ","Mức muốn bỏ cuộc 1/5 đi kèm với việc đạt mục tiêu học tập"]','Nếu mức tập trung 3/5 không thay đổi, khả năng hoàn thành mục tiêu trong các phiên tiếp theo có thể duy trì ở mức ổn định. Nếu thời gian học được chia nhỏ thành các block 30 phút, mức tập trung có khả năng cải thiện lên mức 4/5.','Tín hiệu mức tập trung 3/5 cho thấy khả năng duy trì sự chú ý chưa đạt mức tối đa trong 1 giờ học đầu tiên.','Để xử lý mức tập trung 3/5, áp dụng kỹ thuật chia nhỏ thời gian học thành các block 30 phút để duy trì cường độ chú ý cao nhất.','["Chia thời gian học 1 giờ thành 2 block 30 phút, nghỉ giữa giờ 5 phút trong phiên tiếp theo.","Loại bỏ các thiết bị điện tử không liên quan trong phạm vi 2 mét khi bắt đầu block 30 phút đầu tiên.","Ghi nhận mức tập trung sau mỗi block 30 phút để xác nhận chỉ số đạt mức 4/5."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 30 phút; nếu mức tập trung giảm xuống 2/5 thì điều chỉnh thời gian nghỉ giữa giờ lên 10 phút.','','2026-04-13 08:51:42',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(8,14,29,'2026-04-13','Fluctuating','["Mật độ mất tập trung tăng từ 0.00 lần/giờ ở phiên 1 lên 1.33 lần/giờ ở phiên 3, đi kèm yếu tố gây mất tập trung là test.","Mức bỏ cuộc tăng từ 1/5 ở phiên 1 lên 2/5 ở phiên 3, song song với việc số giờ học duy trì ở mức 1.5h."]','Nếu yếu tố test không thay đổi, mật độ mất tập trung 1.33 lần/giờ có khả năng tiếp tục duy trì hoặc tăng lên, dẫn đến mức bỏ cuộc giữ ở mức 2/5. Nếu việc loại bỏ yếu tố test được thực hiện, mật độ mất tập trung có khả năng cải thiện về mức 0.50 lần/giờ.','Tín hiệu mật độ mất tập trung tăng từ 0.00 lần/giờ ở phiên 1 lên 1.33 lần/giờ ở phiên 3 cho thấy yếu tố test đang trực tiếp làm gián đoạn quy trình học tập, gây ra sự gia tăng mức bỏ cuộc.','Để xử lý yếu tố test, cần thiết lập cơ chế cách ly môi trường học tập khỏi các tác nhân gây gián đoạn trong suốt thời gian học 1.5h.','["Loại bỏ hoàn toàn yếu tố test khỏi không gian học tập trong 48 giờ tới.","Thiết lập khung thời gian học tập cố định 1.5h không có sự xuất hiện của các yếu tố gây mất tập trung đã xác định.","Đo lại mật độ mất tập trung trong phiên tiếp theo để xác nhận chỉ số đạt mức dưới 0.50 lần/giờ."]','Nếu mật độ mất tập trung đạt mức 1.33 lần/giờ trong phiên tiếp theo thì thực hiện thay đổi không gian học tập; nếu mức bỏ cuộc đạt 3/5 thì giảm thời gian học xuống 1h để điều chỉnh áp lực.','','2026-04-13 08:57:57',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(9,15,31,'2026-04-13','Stable','["Mức tập trung 4/5 và số lần mất tập trung 3 lần trong 2 giờ học","Số lần mất tập trung 3 lần với yếu tố gây mất tập trung là ''phone''","Mức muốn bỏ cuộc 2/5 và đạt mục tiêu học tập"]','Nếu yếu tố gây mất tập trung ''phone'' không được kiểm soát, số lần mất tập trung có khả năng tăng lên, ảnh hưởng đến mức tập trung 4/5. Nếu điện thoại được đặt xa tầm tay trong phiên học tiếp theo, mức tập trung có khả năng duy trì ở 4/5 hoặc cao hơn.','Tín hiệu Số lần mất tập trung 3 lần với yếu tố gây mất tập trung là ''phone'' cho thấy sự hiện diện của yếu tố gây xao nhãng có thể ảnh hưởng đến hiệu quả học tập nếu không được kiểm soát.','Để xử lý yếu tố gây mất tập trung ''phone'', cần thiết lập một môi trường học tập không có thiết bị điện tử cá nhân trong phạm vi tiếp cận.','["Người học đặt điện thoại ở chế độ im lặng và để ngoài phòng học trong suốt 2 giờ học tiếp theo.","Người học thông báo với người thân về việc không sử dụng điện thoại trong giờ học để nhận được sự hỗ trợ.","Trong phiên học tiếp theo, số lần mất tập trung cần giảm xuống dưới 1 lần và mức tập trung duy trì ở 4/5 hoặc cao hơn."]','Nếu số lần mất tập trung tăng lên 2 lần trong phiên tiếp theo thì cần áp dụng biện pháp hạn chế sử dụng điện thoại nghiêm ngặt hơn. Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại nguyên nhân mất tập trung.','','2026-04-13 09:44:22',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(10,16,32,'2026-04-13','Stable','["Mức tập trung 4/5 đạt được trong 1.5 giờ học cho thấy khả năng duy trì sự chú ý ở mức cao.","Số lần mất tập trung 2 lần trên 1.5 giờ học tương đương mật độ 1.33 lần/giờ, phản ánh sự gián đoạn thấp trong phiên đầu tiên."]','Nếu mật độ mất tập trung 1.33 lần/giờ không thay đổi, mức tập trung 4/5 có khả năng duy trì ổn định trong các phiên tiếp theo. Nếu thực hiện ghi chép thời điểm mất tập trung, mật độ mất tập trung có khả năng giảm xuống dưới 1 lần/giờ.','Tín hiệu mật độ mất tập trung 1.33 lần/giờ cho thấy đây là yếu tố cần kiểm soát để duy trì hiệu suất học tập ổn định.','Để xử lý mật độ mất tập trung 1.33 lần/giờ, cần áp dụng cơ chế ghi chép nhật ký thời điểm gián đoạn để xác định và loại bỏ các tác nhân gây nhiễu tiềm ẩn.','["Ghi chép lại thời điểm chính xác xảy ra 2 lần mất tập trung trong phiên tiếp theo để phân tích nguyên nhân.","Thiết lập không gian học tập cố định trong 1.5 giờ để kiểm soát các yếu tố gây nhiễu môi trường.","Đo lại mật độ mất tập trung trong phiên kế tiếp, mục tiêu đạt dưới 1 lần/giờ để xác nhận hiệu quả can thiệp."]','Nếu mật độ mất tập trung đạt trên 1.5 lần/giờ trong phiên tiếp theo thì thực hiện rà soát lại môi trường học tập; nếu mức tập trung giảm xuống dưới 3/5 thì thực hiện chia nhỏ thời gian học thành các block 30 phút.','','2026-04-13 09:47:00',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(11,17,33,'2026-04-13','Stable','["Mức tập trung 3/5 đi kèm với 1 lần mất tập trung trong 1 giờ học","Mức muốn bỏ cuộc 1/5 tương ứng với việc đạt mục tiêu trong phiên đầu tiên"]','Nếu mức tập trung 3/5 không thay đổi, tín hiệu 1 lần mất tập trung trong 1 giờ học có khả năng duy trì mật độ gián đoạn tương đương ở phiên tiếp theo. Nếu thời gian học được chia nhỏ thành các block 30 phút, mức tập trung có khả năng cải thiện lên mức 4/5.','Tín hiệu mức tập trung 3/5 đi kèm với 1 lần mất tập trung trong 1 giờ học cho thấy sự phân tán sự chú ý là nguyên nhân gốc rễ làm giảm hiệu suất học tập tối ưu.','Để xử lý mức tập trung 3/5 đi kèm với 1 lần mất tập trung trong 1 giờ học, cần áp dụng kỹ thuật chia nhỏ thời gian học thành các block cố định để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia thời gian học thành 2 block, mỗi block 30 phút với 5 phút nghỉ giữa giờ trong phiên tiếp theo.","Loại bỏ các thiết bị điện tử không liên quan khỏi bàn học trước khi bắt đầu phiên học tiếp theo.","Ghi lại mức tập trung sau mỗi block 30 phút để xác nhận chỉ số đạt mức 4/5."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 30 phút; nếu mức tập trung giảm xuống 2/5 thì thực hiện giảm thời gian block xuống còn 20 phút.','','2026-04-13 09:50:10',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(12,2,35,'2026-04-13','Fluctuating','["Mức tập trung dao động từ 2/5 lên 5/5 rồi xuống 3/5 trong 3 phiên gần nhất, sau đó phục hồi lên 5/5 ở phiên hiện tại.","Mức muốn bỏ cuộc tăng từ 1/5 lên 4/5 trong 2 phiên (phiên -2 và -1), sau đó giảm xuống 2/5 ở phiên hiện tại.","Số giờ học giảm từ 4h ở phiên -2 xuống còn 1.75h ở phiên hiện tại, trong khi mức tập trung tăng từ 5/5 xuống 3/5 rồi lại lên 5/5."]','Nếu Mức tập trung dao động từ 2/5 lên 5/5 rồi xuống 3/5 trong 3 phiên gần nhất, sau đó phục hồi lên 5/5 ở phiên hiện tại không thay đổi, Mức muốn bỏ cuộc có khả năng tăng trở lại từ 2/5 lên mức cao hơn. Nếu thực hiện các bài tập ngắn để củng cố sự tập trung, Mức tập trung có khả năng ổn định ở mức 4/5 hoặc 5/5.','Tín hiệu Mức tập trung dao động từ 2/5 lên 5/5 rồi xuống 3/5 trong 3 phiên gần nhất, sau đó phục hồi lên 5/5 ở phiên hiện tại cho thấy sự thiếu ổn định trong khả năng duy trì sự chú ý, là nguyên nhân gốc dẫn đến các biến động khác.','Để xử lý Mức tập trung dao động từ 2/5 lên 5/5 rồi xuống 3/5 trong 3 phiên gần nhất, sau đó phục hồi lên 5/5 ở phiên hiện tại, cần áp dụng các kỹ thuật ngắt quãng thời gian học tập và xen kẽ các hoạt động ngắn để duy trì sự chú ý liên tục.','["Người học thực hiện 3 phiên học, mỗi phiên kéo dài 45 phút, xen kẽ 5 phút nghỉ giải lao ngắn trong vòng 48 giờ tới.","Giảm thiểu các yếu tố gây xao nhãng bằng cách tắt thông báo trên thiết bị điện tử và thông báo cho người xung quanh về thời gian học tập trong 2 phiên học tới.","Đạt mức tập trung trung bình 4/5 và số lần mất tập trung dưới 1 lần/giờ trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và thực hiện bài tập thư giãn ngắn. Nếu Mức muốn bỏ cuộc tăng lên 3/5 hoặc cao hơn trong phiên tiếp theo thì cần đánh giá lại thời lượng và độ khó của bài học.','','2026-04-13 10:05:08',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(13,2,36,'2026-04-13','High Risk','["Mức tập trung 1/5 ở phiên hiện tại giảm mạnh so với 5/5 ở 2 phiên trước đó (phiên -1 và -3).","Mức muốn bỏ cuộc 1/5 ở phiên hiện tại tăng từ 4/5 ở phiên -2, dù số giờ học chỉ là 0.25h.","Không đạt mục tiêu ở phiên hiện tại, trong khi đạt mục tiêu ở 2/3 phiên gần nhất (phiên -3 và -1)."]','Nếu Mức tập trung 1/5 ở phiên hiện tại giảm mạnh so với 5/5 ở 2 phiên trước đó (phiên -1 và -3) không thay đổi, khả năng không đạt mục tiêu và mức muốn bỏ cuộc tăng cao sẽ tiếp diễn. Nếu có biện pháp tăng cường sự chú ý được thực hiện, mức tập trung có khả năng cải thiện về 3/5 ở phiên tiếp theo.','Tín hiệu Mức tập trung 1/5 ở phiên hiện tại giảm mạnh so với 5/5 ở 2 phiên trước đó (phiên -1 và -3) cho thấy sự suy giảm đột ngột về khả năng duy trì sự chú ý, là nguyên nhân gốc dẫn đến các vấn đề khác.','Để xử lý sự suy giảm đột ngột về khả năng duy trì sự chú ý, cần tập trung vào việc tái thiết lập các thói quen học tập hiệu quả và giảm thiểu các yếu tố gây xao nhãng tiềm ẩn.','["Người học chủ động thực hiện 1 phiên học ngắn 15 phút với 100% sự tập trung vào nội dung bài học, ngay trong vòng 24 giờ tới.","Loại bỏ mọi thiết bị điện tử không cần thiết (điện thoại, máy tính bảng) khỏi không gian học tập trong 48 giờ tới.","Đạt mức tập trung 3/5 và không đạt mục tiêu ở phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 1/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại tình hình. Nếu Mức muốn bỏ cuộc tăng lên 3/5 trong phiên tiếp theo thì cần thực hiện đánh giá nhanh về các yếu tố gây mất tập trung.','','2026-04-13 10:07:19',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(14,2,38,'2026-04-13','Fluctuating','["Mức tập trung phiên hiện tại 5/5 tăng đột biến so với phiên trước 1/5, nhưng số giờ học chỉ 0.25h so với 1.75h ở phiên trước đó.","Mức muốn bỏ cuộc phiên hiện tại 1/5 thấp hơn đáng kể so với phiên trước 4/5, nhưng mục tiêu học tập không đạt ở cả hai phiên.","Mật độ mất tập trung phiên hiện tại 0.00 lần/giờ là mức thấp nhất trong 3 phiên gần nhất, nhưng số giờ học lại giảm mạnh so với phiên trước đó."]','Nếu mức tập trung phiên hiện tại 5/5 tăng đột biến so với phiên trước 1/5, nhưng số giờ học chỉ 0.25h so với 1.75h ở phiên trước đó không thay đổi, khả năng cao là sự tập trung cao này không bền vững và sẽ giảm sút trong các phiên tới. Nếu người học tăng thời lượng học tập lên 1.5h trong phiên tiếp theo, mức tập trung có khả năng duy trì ở mức 4/5.','Tín hiệu Mức tập trung phiên hiện tại 5/5 tăng đột biến so với phiên trước 1/5, nhưng số giờ học chỉ 0.25h so với 1.75h ở phiên trước đó cho thấy sự thiếu ổn định trong phương pháp học tập, không phản ánh sự tiến bộ thực chất.','Để xử lý sự thiếu ổn định trong phương pháp học tập, cần thiết lập một lịch trình học tập có cấu trúc và thời lượng nhất quán hơn, đảm bảo sự cân bằng giữa cường độ tập trung và thời gian học.','["Người học cần cam kết dành ít nhất 1.5 giờ học liên tục trong phiên tiếp theo, bắt đầu ngay sau khi hoàn thành bữa tối.","Trong 1.5 giờ học, người học cần tắt tất cả các thông báo từ mạng xã hội và ứng dụng giải trí trên thiết bị.","Trong phiên tiếp theo, người học cần đạt được ít nhất 1 mục tiêu học tập nhỏ và duy trì mức tập trung trung bình 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu số giờ học trong phiên tiếp theo dưới 1.0h thì cần kích hoạt nhắc nhở học tập ngay lập tức. Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược học tập.','','2026-04-13 16:37:57',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(15,2,39,'2026-04-13','Fluctuating','["Mức tập trung 3/5 ở phiên hiện tại giảm từ 5/5 ở 2 phiên trước đó (phiên -1 và -3)","Mức muốn bỏ cuộc 3/5 ở phiên hiện tại tăng từ 1/5 ở 2 phiên trước đó (phiên -1 và -2)","Số giờ học 1h ở phiên hiện tại giảm so với 1.75h ở phiên -3, trong khi mức tập trung giảm còn 3/5"]','Nếu Mức tập trung 3/5 ở phiên hiện tại giảm từ 5/5 ở 2 phiên trước đó (phiên -1 và -3) không thay đổi, Mức muốn bỏ cuộc có khả năng tăng lên 4/5 ở phiên tiếp theo. Nếu có biện pháp giảm số lần mất tập trung xuống dưới 1 lần/giờ, Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung 3/5 ở phiên hiện tại giảm từ 5/5 ở 2 phiên trước đó (phiên -1 và -3) cho thấy sự bất ổn trong khả năng duy trì sự tập trung cao, đây là yếu tố cốt lõi ảnh hưởng đến hiệu quả học tập.','Để xử lý Mức tập trung 3/5 ở phiên hiện tại giảm từ 5/5 ở 2 phiên trước đó (phiên -1 và -3), cần tập trung vào việc ổn định lại khả năng duy trì sự tập trung bằng cách giảm thiểu các yếu tố gây xao nhãng tiềm ẩn và tăng cường các kỹ thuật giữ sự chú ý.','["Người học chủ động tắt thông báo các ứng dụng không cần thiết trong 1h đầu của phiên học tiếp theo để giảm thiểu yếu tố gây mất tập trung.","Người học thực hiện bài tập hít thở sâu 5 phút trước khi bắt đầu phiên học để chuẩn bị tâm lý và giảm bớt sự bối rối, căng thẳng.","Trong phiên học tiếp theo, Mức tập trung cần đạt 4/5 và Mức muốn bỏ cuộc cần giảm về 2/5 để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và thực hiện bài tập thư giãn 10 phút. Nếu Mức muốn bỏ cuộc tăng lên 4/5 trong phiên tiếp theo thì cần đánh giá lại thời lượng và độ khó của bài học.','','2026-04-13 16:39:50',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(16,19,45,'2026-04-14','Stable','["Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 trong phiên học 1h.","Số lần mất tập trung 4 lần (mật độ 4.00 lần/giờ) trong phiên học 1h.","Đạt mục tiêu phiên học 1h với mức muốn bỏ cuộc 3/5."]','Nếu mức tập trung và mức muốn bỏ cuộc không thay đổi, các phiên học tiếp theo có khả năng duy trì trạng thái cân bằng tương tự. Nếu có hành động giảm số lần mất tập trung xuống dưới 2 lần/giờ, mức tập trung có khả năng cải thiện lên 4/5.','Tín hiệu Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 trong phiên học 1h cho thấy sự cân bằng mong manh giữa nỗ lực và ý định dừng lại, chưa có dấu hiệu rõ ràng về sự suy giảm hoặc cải thiện.','Để xử lý sự cân bằng mong manh giữa mức tập trung và mức muốn bỏ cuộc, cần tập trung vào việc giảm thiểu các yếu tố gây xao nhãng trong môi trường học tập.','["Người học chủ động tắt thông báo các ứng dụng không liên quan trong 1h đầu của phiên học tiếp theo.","Người học tìm một không gian yên tĩnh hơn để học, tránh các khu vực có nhiều tiếng động trong phiên học tiếp theo.","Trong phiên học tiếp theo, người học cần đạt mức tập trung 4/5 và giảm số lần mất tập trung xuống dưới 2 lần/giờ."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung. Nếu số lần mất tập trung tăng lên trên 5 lần trong phiên tiếp theo thì cần tạm dừng phiên học.','','2026-04-14 09:55:02',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(19,20,53,'2026-04-14','Fluctuating','["Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 cho thấy sự cân bằng mong manh.","Số giờ học 1h với Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 cho thấy hiệu quả học tập chưa cao.","Không đạt mục tiêu với Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 cho thấy sự thiếu hiệu quả trong việc hoàn thành nhiệm vụ."]','Nếu Mức tập trung và Mức muốn bỏ cuộc không thay đổi, khả năng không đạt mục tiêu trong phiên tiếp theo là cao. Nếu có hành động tăng cường sự tập trung được thực hiện, Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung 3/5 và Mức muốn bỏ cuộc 3/5 cho thấy sự cân bằng mong manh là nguyên nhân gốc rễ, vì nó phản ánh trực tiếp trạng thái nội tại của người học, ảnh hưởng đến khả năng duy trì sự chú ý và cam kết với mục tiêu học tập.','Để xử lý sự cân bằng mong manh giữa Mức tập trung và Mức muốn bỏ cuộc, cần tập trung vào việc xây dựng các chiến lược giúp người học duy trì sự chú ý và giảm thiểu ý định dừng lại giữa chừng.','["Người học tự áp dụng kỹ thuật Pomodoro (25 phút học, 5 phút nghỉ) trong 1h học tiếp theo để duy trì sự tập trung.","Người học chủ động loại bỏ các yếu tố gây xao nhãng tiềm ẩn bằng cách tắt thông báo điện thoại và đóng các tab không liên quan trên máy tính trong 1h học tiếp theo.","Trong phiên học tiếp theo, Mức tập trung cần đạt 4/5 và Mức muốn bỏ cuộc cần giảm xuống 2/5 để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại tình trạng. Nếu Mức muốn bỏ cuộc tăng lên 4/5 trong phiên tiếp theo thì cần kích hoạt cơ chế hỗ trợ ngay lập tức.','','2026-04-14 13:54:44',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(20,20,54,'2026-04-14','Fluctuating','["Mức tập trung tăng từ 3/5 lên 4/5, trong khi số lần mất tập trung giảm từ 2.00 lần/giờ xuống 0.67 lần/giờ.","Mức muốn bỏ cuộc giảm từ 3/5 xuống 2/5, nhưng mục tiêu vẫn chưa đạt được trong phiên hiện tại.","Số giờ học tăng từ 1h lên 3h, nhưng mức tập trung chỉ tăng 1 bậc."]','Nếu mức tập trung không duy trì ở 4/5 và số lần mất tập trung không tiếp tục giảm, mục tiêu học tập có khả năng tiếp tục không đạt được. Nếu người học thực hiện các bài tập ngắn để củng cố kiến thức ngay sau mỗi giờ học, tỷ lệ đạt mục tiêu có khả năng cải thiện về mức 70% trong phiên tiếp theo.','Tín hiệu Mức tập trung tăng từ 3/5 lên 4/5, trong khi số lần mất tập trung giảm từ 2.00 lần/giờ xuống 0.67 lần/giờ. cho thấy sự cải thiện về khả năng duy trì sự chú ý, tuy nhiên, việc mục tiêu vẫn chưa đạt được cho thấy sự tập trung này chưa đủ sâu hoặc chưa được định hướng hiệu quả.','Để xử lý việc tập trung chưa đủ sâu hoặc chưa được định hướng hiệu quả, cần áp dụng phương pháp học tập chủ động, tập trung vào việc áp dụng kiến thức thay vì chỉ tiếp thu thụ động.','["Người học thực hiện 3 bài tập vận dụng kiến thức đã học trong vòng 30 phút ngay sau khi kết thúc phiên học hôm nay.","Giảm thiểu các yếu tố gây xao nhãng bằng cách tắt thông báo điện thoại và đóng các tab không liên quan trên máy tính trong suốt 3 giờ học của phiên tiếp theo.","Đạt mức tập trung 4/5 và hoàn thành ít nhất 1 mục tiêu học tập trong phiên tiếp theo."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần xem xét lại phương pháp học tập. Nếu số lần mất tập trung tăng lên 2 lần/giờ trong phiên tiếp theo thì cần thực hiện nghỉ giải lao ngắn 5 phút sau mỗi 45 phút học.','','2026-04-14 13:55:23',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(21,2,55,'2026-04-14','Fluctuating','["Mức tập trung 4/5 ở phiên hiện tại tăng từ 2/5 ở 2 phiên trước đó, nhưng vẫn thấp hơn mức 5/5 ghi nhận 7 phiên trước.","Mức muốn bỏ cuộc 2/5 ở phiên hiện tại tăng từ 1/5 ở 2 phiên trước, dù phiên trước đó (S3) có mức bỏ cuộc 4/5.","Số giờ học 0.75h ở phiên hiện tại giảm so với 1h ở 2 phiên trước đó, trong khi mức tập trung tăng."]','Nếu mức tập trung không duy trì ổn định ở mức 4/5 hoặc cao hơn, khả năng cao là mức tập trung sẽ giảm trở lại về 2/5 như các phiên S3 và S4. Nếu duy trì mức tập trung 4/5 và tăng số giờ học lên 1h, mức tập trung có khả năng cải thiện về 4.5/5.','Tín hiệu Mức tập trung 4/5 ở phiên hiện tại tăng từ 2/5 ở 2 phiên trước đó, nhưng vẫn thấp hơn mức 5/5 ghi nhận 7 phiên trước. cho thấy sự phục hồi chưa ổn định, có thể bị ảnh hưởng bởi các yếu tố ngoại cảnh hoặc sự thay đổi trong phương pháp học tập.','Để xử lý sự phục hồi chưa ổn định của mức tập trung, cần tập trung vào việc duy trì sự ổn định và tăng cường hiệu quả học tập trong từng phiên, thay vì chỉ dựa vào sự phục hồi tạm thời.','["Người học cần thực hiện 1 phiên học kéo dài ít nhất 1h với mức tập trung duy trì từ 4/5 trở lên, bắt đầu từ phiên tiếp theo.","Kiểm soát môi trường học tập bằng cách loại bỏ các yếu tố có thể gây gián đoạn, đảm bảo không có yếu tố gây mất tập trung nào xuất hiện trong phiên học tiếp theo.","Đạt mức tập trung 4/5 và số giờ học 1h trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung. Nếu số giờ học dưới 0.75h trong phiên tiếp theo thì cần xem xét lại kế hoạch học tập.','','2026-04-14 13:57:56',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(22,2,57,'2026-04-14','High Risk','["Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở 2 phiên trước đó.","Mức muốn bỏ cuộc 4/5 ở phiên hiện tại tăng từ 1/5 ở 2 phiên trước đó.","Mật độ mất tập trung 1.50 lần/giờ ở phiên hiện tại cao hơn 0.00 lần/giờ ở phiên S6, trong khi mức tập trung giảm từ 3/5 xuống 4/5."]','Nếu mức muốn bỏ cuộc không thay đổi, mức tập trung có khả năng tiếp tục giảm xuống dưới 3/5. Nếu người học thực hiện các hoạt động tăng cường sự hứng thú, mức muốn bỏ cuộc có khả năng giảm về 2/5.','Tín hiệu Mức muốn bỏ cuộc 4/5 ở phiên hiện tại tăng từ 1/5 ở 2 phiên trước đó cho thấy sự suy giảm động lực học tập là nguyên nhân gốc rễ, dẫn đến việc giảm tập trung và không đạt mục tiêu.','Để xử lý mức muốn bỏ cuộc tăng cao, cần tập trung vào việc tái thiết lập sự hứng thú và kết nối lại mục tiêu học tập với các lợi ích cá nhân.','["Người học chủ động dành 15 phút trước phiên học tiếp theo để xem lại mục tiêu học tập và các lý do cá nhân muốn đạt được chúng.","Giảm số lần mất tập trung bằng cách tắt thông báo từ các ứng dụng không liên quan trong suốt thời gian học.","Trong phiên học tiếp theo, người học cần đạt mức muốn bỏ cuộc dưới 3/5 và mức tập trung đạt 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 5/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại nguyên nhân. Nếu mức tập trung giảm xuống dưới 2/5 trong phiên tiếp theo thì cần áp dụng các kỹ thuật lấy lại sự tập trung ngay lập tức.','','2026-04-14 13:58:32',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(23,2,58,'2026-04-15','Fluctuating','["Mức tập trung phiên hiện tại là 4/5, tăng từ 3/5 ở 2 phiên trước, nhưng vẫn thấp hơn mức 4/5 của 3 phiên trước đó.","Mức muốn bỏ cuộc phiên hiện tại là 2/5, giảm từ 4/5 ở 2 phiên trước, nhưng vẫn cao hơn mức 1/5 của 3 phiên trước đó.","Số lần mất tập trung phiên hiện tại là 3 lần (mật độ 1.50 lần/giờ) với yếu tố Mạng xã hội, tương tự mức 2.00 lần/giờ ở phiên -2."]','Nếu Mạng xã hội tiếp tục gây mất tập trung, số lần mất tập trung có khả năng duy trì ở mức 1.50 lần/giờ hoặc cao hơn. Nếu người học chủ động ngắt kết nối mạng xã hội trong 1 giờ học, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Số lần mất tập trung phiên hiện tại là 3 lần (mật độ 1.50 lần/giờ) với yếu tố Mạng xã hội, tương tự mức 2.00 lần/giờ ở phiên -2 cho thấy sự lặp lại của yếu tố gây xao nhãng, ảnh hưởng đến hiệu quả học tập.','Để xử lý Mạng xã hội tiếp tục gây mất tập trung, cần áp dụng cơ chế chặn truy cập hoặc đặt lịch sử dụng có giới hạn thời gian trong các phiên học.','["Người học chủ động tắt thông báo mạng xã hội và đặt chế độ máy bay trong 1 giờ đầu của phiên học tiếp theo.","Kiểm soát môi trường học tập bằng cách đặt điện thoại ở phòng khác trong suốt thời gian học.","Đạt mức tập trung 4/5 và giảm số lần mất tập trung xuống dưới 1 lần/giờ trong phiên học tiếp theo."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần xem xét lại thời gian sử dụng thiết bị điện tử. Nếu số lần mất tập trung tăng lên 2 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần áp dụng biện pháp chặn truy cập mạng xã hội ngay lập tức.','','2026-04-14 23:00:35',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(24,4,59,'2026-04-15','Fluctuating','["Mức tập trung 3/5 không đổi so với phiên trước (3/5), nhưng số giờ học tăng gấp đôi (1h lên 2h).","Mức muốn bỏ cuộc giảm mạnh từ 4/5 ở phiên trước xuống còn 2/5 ở phiên hiện tại, trong khi mục tiêu không đạt.","Số lần mất tập trung (bấm điện thoại) là 2 lần trong 2 giờ học (mật độ 1.00 lần/giờ), tương đương với phiên trước (1 lần/1 giờ)."]','Nếu yếu tố gây mất tập trung (bấm điện thoại) không thay đổi, số lần mất tập trung có khả năng tiếp tục ở mức 1.00 lần/giờ, ảnh hưởng đến việc đạt mục tiêu. Nếu người học chủ động đặt điện thoại xa tầm tay trong 1 giờ đầu, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Số lần mất tập trung (bấm điện thoại) là 2 lần trong 2 giờ học (mật độ 1.00 lần/giờ), tương đương với phiên trước (1 lần/1 giờ) cho thấy yếu tố gây mất tập trung chưa được giải quyết và có khả năng tái diễn.','Để xử lý yếu tố gây mất tập trung (bấm điện thoại), cần thiết lập quy trình kiểm soát việc sử dụng thiết bị cá nhân trong giờ học.','["Người học đặt điện thoại ở chế độ im lặng và để ngoài tầm với trong suốt 2 giờ học của phiên tiếp theo.","Giảm thiểu các yếu tố gây xao nhãng bằng cách đóng các tab không liên quan trên máy tính và thông báo cho người thân không làm phiền trong giờ học.","Trong phiên tiếp theo, người học cần đạt mức tập trung 4/5 và số lần mất tập trung dưới 1 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và thực hiện các bài tập phục hồi khả năng tập trung. Nếu số lần mất tập trung vượt quá 2 lần trong 1 giờ đầu của phiên tiếp theo thì cần áp dụng biện pháp cách ly thiết bị điện tử ngay lập tức.','','2026-04-15 00:29:19',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(27,2,65,'2026-04-15','High Risk','["Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở phiên trước (S1)","Mức muốn bỏ cuộc 4/5 ở phiên hiện tại duy trì từ 2 phiên trước (S7, S8)","Số giờ học 6h ở phiên hiện tại cao hơn đáng kể so với 2h ở 3 phiên gần nhất"]','Nếu mức muốn bỏ cuộc 4/5 không thay đổi, mức tập trung 3/5 có khả năng giảm xuống dưới 3/5 trong các phiên tới. Nếu người học thực hiện giảm số lần mất tập trung xuống dưới 1.50 lần/giờ, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức muốn bỏ cuộc 4/5 ở phiên hiện tại duy trì từ 2 phiên trước (S7, S8) cho thấy sự kiên trì đang giảm sút, là nguyên nhân gốc dẫn đến việc khó đạt mục tiêu và có thể ảnh hưởng tiêu cực đến mức tập trung trong các phiên tới.','Để xử lý mức muốn bỏ cuộc 4/5 đang duy trì, cần tập trung vào việc xây dựng lại cảm giác hoàn thành và tiến bộ trong học tập, giảm thiểu các yếu tố gây nản lòng.','["Người học chủ động chia nhỏ mục tiêu học tập trong phiên tiếp theo, hoàn thành từng phần nhỏ trong vòng 1 giờ học để tạo cảm giác hoàn thành liên tục.","Giảm thời gian học liên tục xuống còn 2 giờ mỗi phiên, xen kẽ nghỉ ngơi 15 phút sau mỗi giờ học để tránh quá tải.","Đạt mức muốn bỏ cuộc dưới 3/5 và mức tập trung đạt 4/5 trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 5/5 trong phiên tiếp theo thì cần tạm dừng phiên học. Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược chia nhỏ mục tiêu.','','2026-04-15 00:47:42',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(28,4,66,'2026-04-15','Fluctuating','["Mức tập trung 3/5 không đổi trong 3 phiên, trong khi số giờ học thay đổi (1h, 2h, 1h)","Số lần mất tập trung tăng gấp đôi từ 1 lần/giờ lên 2 lần/giờ trong phiên hiện tại, đi kèm với việc bấm điện thoại","Mức muốn bỏ cuộc giảm từ 4/5 ở phiên trước xuống 2/5 ở phiên hiện tại, dù mục tiêu không đạt ở phiên trước đó"]','Nếu số lần mất tập trung và việc bấm điện thoại không thay đổi, mức tập trung 3/5 có khả năng duy trì hoặc giảm nhẹ trong các phiên tới. Nếu việc bấm điện thoại được hạn chế, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Số lần mất tập trung tăng gấp đôi từ 1 lần/giờ lên 2 lần/giờ trong phiên hiện tại, đi kèm với việc bấm điện thoại cho thấy yếu tố gây mất tập trung bên ngoài đang trực tiếp ảnh hưởng đến hiệu quả học tập.','Để xử lý việc bấm điện thoại gây mất tập trung, cần áp dụng cơ chế tự kiểm soát thời gian sử dụng thiết bị di động trong giờ học.','["Người học tự đặt hẹn giờ 30 phút không sử dụng điện thoại trong phiên học tiếp theo, bắt đầu từ 08:00.","Trong phiên học tiếp theo, người học đặt điện thoại ở chế độ im lặng và để ngoài tầm với trong suốt 1 giờ học.","Ở phiên học tiếp theo, mức tập trung cần đạt 4/5 và số lần mất tập trung giảm xuống dưới 1 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học 15 phút. Nếu số lần mất tập trung vượt quá 2 lần/giờ trong phiên tiếp theo thì cần thực hiện lại hành động 1 và 2.','','2026-04-15 01:03:59',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(29,21,67,'2026-04-15','Stable','["Mức tập trung 3/5 và Mức muốn bỏ cuộc 1/5 trong phiên học 2h.","Số lần mất tập trung 0 lần (mật độ 0.00 lần/giờ) với yếu tố gây mất tập trung là điện thoại.","Đạt mục tiêu Có và Trạng thái cảm xúc Có động lực, Tập trung cao trong phiên học 2h."]','Nếu Mức tập trung 3/5 và Mức muốn bỏ cuộc 1/5 không thay đổi, khả năng duy trì trạng thái học tập hiện tại là cao. Nếu có hành động giảm thiểu yếu tố gây mất tập trung như điện thoại, Mức tập trung có khả năng cải thiện lên 4/5.','Tín hiệu Mức tập trung 3/5 và Mức muốn bỏ cuộc 1/5 trong phiên học 2h cho thấy sự cân bằng hiện tại giữa nỗ lực và mong muốn tiếp tục, chưa có dấu hiệu suy giảm.','Để xử lý Mức tập trung 3/5 và Mức muốn bỏ cuộc 1/5, cần củng cố các yếu tố tích cực đã có và ngăn chặn các yếu tố tiềm ẩn gây xao nhãng.','["Người học chủ động đặt điện thoại ở chế độ im lặng và để xa tầm tay trong 2h của phiên học tiếp theo.","Người học ghi nhận lại các yếu tố đã giúp đạt mục tiêu và duy trì tập trung trong phiên hiện tại để áp dụng cho phiên tiếp theo.","Trong phiên học tiếp theo, Mức tập trung cần đạt 4/5 và Mức muốn bỏ cuộc cần duy trì ở 1/5 để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung. Nếu Mức muốn bỏ cuộc tăng lên 2/5 trong phiên tiếp theo thì cần tìm hiểu nguyên nhân và có biện pháp hỗ trợ kịp thời.','','2026-04-15 12:27:25',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(30,5,71,'2026-04-15','Stable','["Mức tập trung 4/5 duy trì ổn định ở 2 phiên gần nhất, tăng từ 3/5 ở phiên trước đó.","Số lần mất tập trung 7 lần (mật độ 1.40 lần/giờ) trong phiên hiện tại, tương đương với phiên trước (1.40 lần/giờ) và giảm nhẹ so với phiên trước đó (1.67 lần/giờ).","Mức muốn bỏ cuộc 2/5 duy trì ổn định trong cả 3 phiên, trong khi số giờ học tăng từ 3h lên 5h ở phiên hiện tại."]','Nếu mức tập trung 4/5 duy trì ổn định, khả năng đạt mục tiêu trong các phiên tới là cao. Nếu có hành động giảm thiểu yếu tố gây mất tập trung như mạng xã hội và điện thoại, mức tập trung có khả năng cải thiện lên 5/5.','Tín hiệu Mức tập trung 4/5 duy trì ổn định ở 2 phiên gần nhất, tăng từ 3/5 ở phiên trước đó cho thấy khả năng phục hồi và duy trì sự tập trung tốt, không có dấu hiệu suy giảm.','Để xử lý việc duy trì mức tập trung ổn định và có động lực học tập, cần tập trung vào việc củng cố các thói quen tích cực đã hình thành và hạn chế các yếu tố gây xao nhãng tiềm ẩn.','["Người học chủ động tắt thông báo mạng xã hội và đặt điện thoại ở chế độ im lặng trong suốt 5 giờ học của phiên tiếp theo.","Người học chuẩn bị sẵn sàng các tài liệu học tập và không gian học yên tĩnh trước khi bắt đầu phiên học 2 giờ tiếp theo.","Mức tập trung cần đạt 4/5 và số lần mất tập trung dưới 5 lần trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung. Nếu số lần mất tập trung tăng lên trên 7 lần trong phiên tiếp theo thì cần thực hiện các biện pháp ngắt kết nối với thiết bị điện tử.','','2026-04-15 14:30:07',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(31,23,70,'2026-04-15','Stable','["Mức tập trung 4/5 và Mức muốn bỏ cuộc 3/5 trong phiên học 9 giờ.","Số lần mất tập trung 5 lần (mật độ 0.56 lần/giờ) với yếu tố gây mất tập trung là Bài tập khó."]','Nếu yếu tố gây mất tập trung Bài tập khó không được giải quyết, số lần mất tập trung có khả năng tăng lên, ảnh hưởng đến Mức tập trung. Nếu bài tập được chia nhỏ và có hướng dẫn rõ ràng hơn, Mức tập trung có khả năng cải thiện về 4/5 hoặc cao hơn.','Tín hiệu Số lần mất tập trung 5 lần (mật độ 0.56 lần/giờ) với yếu tố gây mất tập trung là Bài tập khó cho thấy sự ảnh hưởng trực tiếp của nội dung học đến khả năng duy trì sự tập trung.','Để xử lý yếu tố gây mất tập trung Bài tập khó, cần điều chỉnh phương pháp tiếp cận nội dung học để giảm thiểu cảm giác quá tải và tăng khả năng xử lý.','["Người học chủ động chia nhỏ Bài tập khó thành các phần nhỏ hơn và tìm kiếm tài liệu hỗ trợ hoặc hỏi giảng viên/bạn bè trong vòng 1 giờ tới.","Trong 2 giờ học tiếp theo, người học sẽ áp dụng kỹ thuật Pomodoro (25 phút học, 5 phút nghỉ) để quản lý thời gian và giảm thiểu mệt mỏi, căng thẳng.","Trong phiên học tiếp theo, Mức tập trung cần đạt 4/5 và Số lần mất tập trung giảm xuống dưới 3 lần để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng bài tập khó và chuyển sang nội dung khác. Nếu Số lần mất tập trung vượt quá 5 lần trong phiên tiếp theo thì cần đánh giá lại phương pháp chia nhỏ bài tập.','','2026-04-15 14:31:42',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(32,10,75,'2026-04-15','High Risk','["Mức tập trung 3/5 không đổi trong 6 phiên, trong khi Mức muốn bỏ cuộc duy trì ở 5/5 trong 5 phiên gần nhất.","Số lần mất tập trung 10 lần (mật độ 3.33 lần/giờ) và Đạt mục tiêu: Không trong phiên hiện tại, lặp lại xu hướng của 3 phiên gần nhất.","Yếu tố gây mất tập trung ''Nhắn tin với em mập mờ'' xuất hiện trong phiên hiện tại, đi kèm với Mức muốn bỏ cuộc 5/5."]','Nếu Mức muốn bỏ cuộc 5/5 không thay đổi, Mức tập trung 3/5 có khả năng không cải thiện và Đạt mục tiêu: Không sẽ tiếp diễn. Nếu có biện pháp giảm thiểu yếu tố gây mất tập trung ''Nhắn tin với em mập mờ'', Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức muốn bỏ cuộc 5/5 duy trì trong 5 phiên gần nhất, đi kèm với việc không đạt mục tiêu, cho thấy sự suy giảm ý chí học tập dai dẳng là nguyên nhân gốc rễ, dẫn đến việc duy trì mức tập trung thấp và không hoàn thành mục tiêu.','Để xử lý Mức muốn bỏ cuộc 5/5 duy trì, cần tập trung vào việc tái thiết lập động lực học tập bằng cách chia nhỏ mục tiêu và tạo ra các điểm thưởng nhỏ khi hoàn thành từng phần.','["Người học chủ động đặt ra 2 mục tiêu nhỏ hơn cho phiên học tiếp theo, mỗi mục tiêu hoàn thành trong 1.5 giờ học, bắt đầu từ phiên 2026-04-16.","Trong phiên học tiếp theo, người học tắt thông báo điện thoại và đặt điện thoại ở chế độ im lặng trong suốt 3 giờ học để giảm thiểu Yếu tố gây mất tập trung ''Nhắn tin với em mập mờ''.","Trong phiên học tiếp theo, người học cần đạt Mức tập trung 4/5 và hoàn thành ít nhất 1 trong 2 mục tiêu nhỏ đã đề ra để xác nhận can thiệp có hiệu quả."]','Nếu Mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì người học cần tạm dừng các hoạt động học tập và thực hiện bài tập thư giãn ngắn 15 phút. Nếu số lần mất tập trung vượt quá 5 lần trong phiên tiếp theo thì người học cần dừng học ngay lập tức và thực hiện hoạt động khác trong 30 phút trước khi quay lại.','','2026-04-15 14:38:01',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(33,25,77,'2026-04-16','Fluctuating','["Mức tập trung tăng từ 3/5 lên 4/5, trong khi số lần mất tập trung giảm từ 4 lần/giờ xuống 1.33 lần/giờ.","Mức muốn bỏ cuộc giảm từ 3/5 xuống 2/5, nhưng mục tiêu học tập không đạt được ở phiên hiện tại.","Số giờ học tăng từ 0.25h lên 1.5h, với số lần mất tập trung giảm đáng kể."]','Nếu mức tập trung và số lần mất tập trung không thay đổi, mục tiêu học tập có khả năng tiếp tục không đạt được. Nếu việc sử dụng mạng xã hội được kiểm soát, mức tập trung có khả năng cải thiện về 4.5/5.','Tín hiệu Mức tập trung tăng từ 3/5 lên 4/5, trong khi số lần mất tập trung giảm từ 4 lần/giờ xuống 1.33 lần/giờ. cho thấy sự cải thiện về khả năng duy trì sự chú ý, tuy nhiên, việc không đạt mục tiêu học tập cho thấy sự tập trung này chưa đủ hiệu quả để hoàn thành nhiệm vụ.','Để xử lý sự mất tập trung do mạng xã hội, cần áp dụng các biện pháp hạn chế truy cập trong thời gian học.','["Người học chủ động tắt thông báo mạng xã hội và đặt điện thoại ở chế độ im lặng trong suốt 1.5 giờ học của phiên tiếp theo.","Người học ghi lại các yếu tố gây xao nhãng cụ thể (ví dụ: tin nhắn, thông báo) trong phiên học tiếp theo để đánh giá lại mật độ mất tập trung.","Trong phiên tiếp theo, người học cần đạt được ít nhất 1 mục tiêu học tập đã đề ra và duy trì mức tập trung 4/5 hoặc cao hơn để xác nhận can thiệp có hiệu quả."]','Nếu số lần mất tập trung tăng lên 2 lần/giờ trong phiên tiếp theo thì cần xem xét lại các biện pháp hạn chế mạng xã hội. Nếu mục tiêu học tập không đạt được trong phiên tiếp theo thì cần đánh giá lại khối lượng bài tập.','','2026-04-16 01:20:09',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(36,23,84,'2026-04-16','Fluctuating','["Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học giảm từ 9h xuống 5h.","Số lần mất tập trung tăng từ 0.56 lần/giờ lên 0.60 lần/giờ, với các yếu tố gây mất tập trung là nói chuyện với bạn bè và xem phim.","Mức muốn bỏ cuộc giữ nguyên ở 3/5 dù mức tập trung giảm."]','Nếu Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học giảm từ 9h xuống 5h không thay đổi, Mức muốn bỏ cuộc có khả năng tăng lên. Nếu các yếu tố gây mất tập trung như nói chuyện với bạn bè và xem phim được hạn chế, Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học giảm từ 9h xuống 5h cho thấy sự suy giảm về khả năng duy trì sự chú ý, đây là nguyên nhân gốc rễ dẫn đến các vấn đề khác.','Để xử lý Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học giảm từ 9h xuống 5h, cần tập trung vào việc giảm thiểu các yếu tố gây xao nhãng bên ngoài và tăng cường sự chủ động trong việc duy trì sự chú ý.','["Người học chủ động thông báo cho bạn bè về thời gian học tập và tắt thông báo các ứng dụng giải trí trong 2 giờ đầu của phiên học tiếp theo.","Thiết lập môi trường học tập yên tĩnh, tránh xa các thiết bị có thể gây xao nhãng như điện thoại hoặc TV trong suốt phiên học.","Đạt mức tập trung 4/5 và giảm số lần mất tập trung xuống dưới 0.5 lần/giờ trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại nguyên nhân. Nếu số lần mất tập trung vượt quá 0.7 lần/giờ trong phiên tiếp theo thì cần áp dụng biện pháp ngắt quãng học tập ngắn (5 phút) sau mỗi 45 phút học.','','2026-04-16 14:52:47',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(37,26,86,'2026-04-17','Stable','["Mức tập trung 4/5 giữ ổn định so với phiên trước (4/5)","Mức muốn bỏ cuộc 3/5 giữ ổn định so với phiên trước (3/5)","Số lần mất tập trung 4 lần (mật độ 2.67 lần/giờ) giữ ổn định so với phiên trước (mật độ 2.67 lần/giờ)"]','Nếu Mức tập trung 4/5 giữ ổn định không thay đổi, số lần mất tập trung 4 lần có khả năng tiếp tục duy trì ở mức hiện tại. Nếu việc sử dụng điện thoại được hạn chế, Mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung 4/5 giữ ổn định so với phiên trước (4/5) cho thấy sự ổn định trong khả năng duy trì sự chú ý, không có dấu hiệu suy giảm.','Để xử lý sự ổn định của Mức tập trung 4/5, cần tập trung vào việc giảm thiểu các yếu tố gây mất tập trung đã được ghi nhận.','["Người học chủ động đặt điện thoại ở chế độ im lặng và để xa tầm tay trong suốt 1.5h của phiên học tiếp theo.","Kiểm soát môi trường học tập bằng cách thông báo cho người cùng nhà về thời gian học để hạn chế tiếng ồn hoặc sự làm phiền trong 1.5h của phiên học tiếp theo.","Đạt mức tập trung 5/5 và số lần mất tập trung dưới 2 lần trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần đánh giá lại nguyên nhân mất tập trung. Nếu Số lần mất tập trung tăng lên 4 lần hoặc hơn trong phiên tiếp theo thì cần thực hiện các biện pháp can thiệp bổ sung.','','2026-04-17 00:55:29',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(39,23,89,'2026-04-17','Fluctuating','["Mức tập trung dao động 4 → 3 → 4 trong 3 phiên gần nhất.","Mức muốn bỏ cuộc giảm từ 3/5 ở 2 phiên trước xuống còn 2/5 ở phiên hiện tại, trong khi số giờ học giảm từ 9h xuống còn 5h.","Số lần mất tập trung tăng từ 0.56 lần/giờ lên 0.60 lần/giờ ở phiên trước, dù mức tập trung giảm và số giờ học giảm."]','Nếu sự dao động về mức tập trung không thay đổi, phiên học tiếp theo có khả năng chứng kiến mức tập trung giảm xuống dưới 4/5. Nếu người học chủ động áp dụng kỹ thuật quản lý năng lượng, mức tập trung có khả năng cải thiện về 4/5 hoặc cao hơn.','Tín hiệu Mức tập trung dao động 4 → 3 → 4 trong 3 phiên gần nhất cho thấy sự thiếu ổn định trong khả năng duy trì hiệu suất học tập.','Để xử lý sự thiếu ổn định trong khả năng duy trì hiệu suất học tập, cần tập trung vào việc xây dựng quy trình học tập có cấu trúc rõ ràng, bao gồm các khoảng nghỉ ngắn xen kẽ để duy trì năng lượng và sự tập trung.','["Người học thực hiện chia nhỏ thời gian học thành các khối 45 phút, xen kẽ 10 phút nghỉ ngơi, trong 2 phiên học tới.","Giảm thiểu các yếu tố gây mất tập trung bằng cách tắt thông báo điện thoại và đóng các tab không liên quan trên máy tính trong suốt các khối học.","Đạt mức tập trung 4/5 và giảm số lần mất tập trung xuống dưới 0.5 lần/giờ trong phiên học tiếp theo."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược chia nhỏ thời gian học. Nếu số lần mất tập trung tăng lên 0.7 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần áp dụng biện pháp ngắt kết nối khỏi thiết bị điện tử trong 15 phút.','','2026-04-17 14:49:39',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(40,5,90,'2026-04-17','High Risk','["Mức tập trung giảm từ 4/5 ở 2 phiên trước xuống còn 2/5 ở phiên hiện tại, trong khi số giờ học chỉ là 4h.","Số lần mất tập trung tăng lên 5 lần (mật độ 1.25 lần/giờ) ở phiên hiện tại, cao hơn so với các phiên trước có mật độ dưới 1.5 lần/giờ.","Không đạt mục tiêu ở phiên hiện tại (2/5), khác với 3 phiên trước đều đạt mục tiêu."]','Nếu mức tập trung tiếp tục ở mức 2/5 và số lần mất tập trung vẫn cao, khả năng không đạt mục tiêu ở phiên tiếp theo là rất cao. Nếu tiếng ồn được kiểm soát, mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu mức tập trung giảm từ 4/5 xuống còn 2/5 cho thấy sự suy giảm hiệu suất học tập rõ rệt, là nguyên nhân chính dẫn đến việc không đạt mục tiêu và có thể làm tăng nguy cơ bỏ cuộc nếu kéo dài.','Để xử lý tình trạng mất tập trung do tiếng ồn, cần áp dụng biện pháp giảm thiểu nguồn gây xao nhãng từ môi trường bên ngoài.','["Người học chủ động tìm và sử dụng tai nghe chống ồn hoặc di chuyển đến khu vực yên tĩnh hơn trong 2 giờ đầu của phiên học tiếp theo.","Kiểm soát yếu tố tiếng ồn bằng cách thông báo với người xung quanh về thời gian học tập hoặc sử dụng ứng dụng chặn tiếng ồn nếu có thể, trong suốt phiên học tiếp theo.","Đạt mức tập trung 3/5 và giảm số lần mất tập trung xuống dưới 3 lần trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 2/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại tình hình. Nếu số lần mất tập trung vượt quá 5 lần trong phiên tiếp theo thì cần áp dụng biện pháp can thiệp mạnh hơn.','','2026-04-17 14:50:19',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(41,27,93,'2026-04-18','Fluctuating','["Mức tập trung 3/5 và số lần mất tập trung 6 lần trong phiên hiện tại","Mật độ mất tập trung 8.00 lần/giờ và yếu tố gây mất tập trung là Mạng xã hội trong phiên hiện tại","Không đạt mục tiêu và Mức muốn bỏ cuộc 2/5 trong phiên hiện tại"]','Nếu Mạng xã hội tiếp tục là yếu tố gây mất tập trung với mật độ 8.00 lần/giờ, Mức tập trung 3/5 có khả năng giảm xuống dưới 3/5 trong các phiên tiếp theo. Nếu việc sử dụng Mạng xã hội được hạn chế, Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mật độ mất tập trung 8.00 lần/giờ và yếu tố gây mất tập trung là Mạng xã hội trong phiên hiện tại cho thấy sự hiện diện rõ ràng của yếu tố gây xao nhãng có thể làm giảm hiệu quả học tập.','Để xử lý Mạng xã hội là yếu tố gây mất tập trung với mật độ cao, cần áp dụng biện pháp kiểm soát truy cập và tạo môi trường học tập không bị gián đoạn bởi các thông báo hoặc cám dỗ từ mạng xã hội.','["Người học sẽ tắt thông báo và đặt điện thoại ở chế độ im lặng, để xa tầm tay trong suốt 1 giờ học đầu tiên của phiên tiếp theo.","Người học sẽ sử dụng ứng dụng chặn truy cập mạng xã hội trong thời gian học đã lên lịch.","Trong phiên tiếp theo, Mức tập trung cần đạt ít nhất 4/5 và Số lần mất tập trung dưới 3 lần để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần xem xét lại thời gian học. Nếu Số lần mất tập trung vượt quá 5 lần trong phiên tiếp theo thì cần áp dụng biện pháp mạnh hơn để hạn chế Mạng xã hội.','','2026-04-18 02:30:37',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(46,30,100,'2026-04-18','High Risk','["Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5 trong phiên hiện tại","Số lần mất tập trung 60 lần (30 lần/giờ) với yếu tố điện thoại trong phiên hiện tại","Không đạt mục tiêu và Mức tập trung 2/5 trong phiên hiện tại"]','Nếu Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5 không thay đổi, số lần mất tập trung có khả năng tiếp tục ở mức cao 60 lần. Nếu người học chủ động đặt điện thoại ra xa trong 15 phút đầu phiên, Mức tập trung có khả năng cải thiện lên 3/5.','Tín hiệu Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5 trong phiên hiện tại cho thấy sự suy giảm hiệu suất học tập rõ rệt, có khả năng dẫn đến việc dừng buổi học.','Để xử lý Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5, cần tập trung vào việc giảm thiểu các yếu tố gây xao nhãng trực tiếp từ môi trường học tập.','["Người học đặt điện thoại ở chế độ im lặng và để ngoài tầm với trong suốt 2 giờ học của phiên tiếp theo.","Người học thông báo với người thân về việc cần tập trung và yêu cầu không làm phiền trong 2 giờ học của phiên tiếp theo.","Trong phiên tiếp theo, Mức tập trung cần đạt tối thiểu 3/5 và Mức muốn bỏ cuộc giảm xuống 3/5 để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 2/5 trong phiên tiếp theo thì cần tạm dừng buổi học và đánh giá lại tình hình. Nếu Mức muốn bỏ cuộc tăng lên 5/5 trong phiên tiếp theo thì cần dừng buổi học ngay lập tức.','','2026-04-18 12:27:10',NULL,NULL);
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(47,18,102,'2026-04-18','Fluctuating','["Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở 2 phiên trước đó.","Số lần mất tập trung 5 lần (mật độ 1.67 lần/giờ) ở phiên hiện tại tăng so với 0.67 lần/giờ ở phiên S4.","Mức muốn bỏ cuộc 2/5 ở phiên hiện tại tương đương với phiên S5 (2/5) nhưng cao hơn 1/5 ở phiên S4."]','Nếu Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở 2 phiên trước đó không thay đổi, số lần mất tập trung có khả năng tiếp tục tăng. Nếu việc giảm đau bụng được thực hiện, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở 2 phiên trước đó cho thấy sự suy giảm hiệu suất học tập liên tục trong các phiên gần đây.','Để xử lý sự suy giảm hiệu suất học tập liên tục trong các phiên gần đây, cần tập trung vào việc giảm thiểu các yếu tố gây mất tập trung.','["Người học chủ động thực hiện các biện pháp giảm đau bụng trong 1 giờ đầu của phiên học tiếp theo.","Loại bỏ các thiết bị điện tử không cần thiết trong vòng 2 mét xung quanh khu vực học tập trong suốt phiên học tiếp theo.","Đạt mức tập trung 4/5 và số lần mất tập trung dưới 1 lần/giờ trong phiên học tiếp theo."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại tình trạng sức khỏe. Nếu số lần mất tập trung vượt quá 3 lần trong phiên tiếp theo thì cần áp dụng biện pháp nghỉ giải lao ngắn 5 phút sau mỗi 30 phút học.','','2026-04-18 13:30:28','gemini-2.5-flash-lite','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(48,32,103,'2026-04-18','Fluctuating','["Mức tập trung 2/5 và Mức muốn bỏ cuộc 1/5 cho thấy sự không ổn định trong phiên học.","Số giờ học 1h với Mức tập trung 2/5 cho thấy hiệu quả học tập chưa cao.","Số lần mất tập trung 1 lần/giờ với Mức tập trung 2/5 cho thấy có yếu tố ảnh hưởng đến sự tập trung."]','Nếu thời lượng học và mức tập trung không thay đổi, số giờ học 1h với mức tập trung 2/5 có khả năng tiếp tục duy trì hiệu quả học tập thấp. Nếu có hành động điều chỉnh thời lượng học phù hợp, mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu Số giờ học 1h với Mức tập trung 2/5 cho thấy nguyên nhân gốc rễ là thời lượng học chưa đủ để duy trì sự tập trung cao, dẫn đến hiệu quả chưa tối ưu.','Để xử lý thời lượng học chưa đủ để duy trì sự tập trung cao, cần điều chỉnh lại kế hoạch học tập để phân bổ thời gian học hợp lý hơn, tránh học liên tục quá lâu hoặc quá ngắn.','["Người học sẽ điều chỉnh lại lịch học, chia thành các phiên học ngắn hơn (ví dụ: 30 phút học, 10 phút nghỉ) trong vòng 48 giờ tới.","Người học sẽ chủ động loại bỏ các yếu tố gây mất tập trung tiềm ẩn (ví dụ: tắt thông báo điện thoại) trước mỗi phiên học trong vòng 48 giờ tới.","Trong phiên học tiếp theo, Mức tập trung cần đạt ít nhất 3/5 và Số lần mất tập trung dưới 0.5 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 2/5 trong phiên tiếp theo thì cần xem xét lại chiến lược phân bổ thời gian học. Nếu Số lần mất tập trung tăng lên 2 lần/giờ trong phiên tiếp theo thì cần đánh giá lại các yếu tố môi trường học tập.','','2026-04-18 13:35:35','gemini-2.5-flash-lite','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(49,32,105,'2026-04-18','High Risk','["Mức tập trung 2/5 không đổi so với phiên trước (2/5), nhưng số giờ học tăng gấp đôi (1h lên 2h).","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại.","Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5 cùng xuất hiện ở phiên hiện tại, trong khi phiên trước đạt mục tiêu với Mức bỏ cuộc 1/5."]','Nếu Mức muốn bỏ cuộc tiếp tục ở mức 4/5, Mức tập trung 2/5 có khả năng duy trì hoặc giảm thêm trong các phiên tới. Nếu người học thực hiện các bài tập ngắn để lấy lại hứng thú, Mức muốn bỏ cuộc có khả năng giảm về dưới 2/5.','Tín hiệu Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại cho thấy sự suy giảm động lực học tập rõ rệt, là nguyên nhân gốc dẫn đến các biểu hiện khác.','Để xử lý Mức muốn bỏ cuộc tăng cao, cần tập trung vào việc tái thiết lập sự hứng thú và cảm giác hoàn thành mục tiêu thông qua việc chia nhỏ nhiệm vụ và ghi nhận các thành tựu nhỏ.','["Người học thực hiện 1 bài tập ngắn (tối đa 30 phút) với mục tiêu hoàn thành rõ ràng trong phiên học tiếp theo.","Giảm thời lượng học xuống còn 1h trong phiên tiếp theo và loại bỏ các yếu tố gây xao nhãng tiềm ẩn bằng cách đóng các tab không liên quan trên trình duyệt.","Đạt Mức muốn bỏ cuộc dưới 2/5 và hoàn thành ít nhất 1 bài tập nhỏ trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức muốn bỏ cuộc đạt 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và thực hiện bài tập thư giãn ngắn. Nếu Mức tập trung giảm xuống dưới 1/5 trong phiên tiếp theo thì cần đánh giá lại toàn bộ kế hoạch học tập.','','2026-04-18 13:37:02','gemini-2.5-flash-lite','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(51,18,104,'2026-04-18','High Risk','["Mức tập trung giảm từ 3/5 ở 2 phiên trước xuống còn 2/5 ở phiên hiện tại, trong khi số giờ học giảm từ 3h xuống còn 1.25h.","Số lần mất tập trung tăng từ 1.67 lần/giờ ở 2 phiên trước lên 3.20 lần/giờ ở phiên hiện tại, dù mức độ muốn bỏ cuộc giữ nguyên ở 2/5.","Mức tập trung giảm còn 2/5, thấp hơn 2 bậc so với 4/5 ở phiên S4 (phiên -3), trong khi số lần mất tập trung tăng gấp 4 lần."]','Nếu mức tập trung tiếp tục giảm và số giờ học không tăng, khả năng cao là hiệu suất học tập sẽ tiếp tục đi xuống. Nếu người học chủ động tăng thời gian học lên 3h và duy trì mức tập trung 3/5, các chỉ số có khả năng cải thiện.','Tín hiệu Mức tập trung giảm từ 3/5 ở 2 phiên trước xuống còn 2/5 ở phiên hiện tại, trong khi số giờ học giảm từ 3h xuống còn 1.25h cho thấy sự suy giảm hiệu suất học tập kéo dài.','Để xử lý sự suy giảm hiệu suất học tập kéo dài, cần tập trung vào việc tăng cường thời gian học và giảm thiểu các yếu tố gây mất tập trung.','["Người học cần tăng thời gian học lên tối thiểu 3 giờ trong phiên tiếp theo, tập trung vào các nhiệm vụ đã đề ra.","Giảm thiểu các yếu tố gây mất tập trung bằng cách tắt thông báo điện thoại và đóng các tab không liên quan trên máy tính trong suốt thời gian học.","Đạt mức tập trung 3/5 và giảm số lần mất tập trung xuống dưới 2 lần/giờ trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 2/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại nguyên nhân. Nếu số lần mất tập trung vượt quá 4 lần/giờ trong phiên tiếp theo thì cần áp dụng biện pháp ngắt quãng học tập 5 phút sau mỗi 25 phút học.','','2026-04-18 13:39:25','gemini-2.5-flash-lite','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(53,18,109,'2026-04-18','Fluctuating','["Mức tập trung phiên hiện tại là 3/5, giảm từ 2/5 ở phiên trước (phiên 7) nhưng vẫn cao hơn mức trung bình 3 phiên gần nhất là 2.67/5.","Mật độ mất tập trung tăng từ 1.67 lần/giờ ở phiên 6 lên 3.20 lần/giờ ở phiên 7, và duy trì ở mức 4.00 lần/giờ trong phiên hiện tại.","Mức muốn bỏ cuộc duy trì ở 2/5 trong 5 phiên gần nhất, nhưng có xu hướng tăng nhẹ từ 1/5 ở phiên 4 lên 2/5 ở phiên 7 và phiên hiện tại."]','Nếu mật độ mất tập trung không giảm, mức tập trung có khả năng giảm xuống dưới 3/5 trong các phiên tới. Nếu các yếu tố gây mất tập trung được loại bỏ, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mật độ mất tập trung tăng từ 1.67 lần/giờ ở phiên 6 lên 3.20 lần/giờ ở phiên 7, và duy trì ở mức 4.00 lần/giờ trong phiên hiện tại cho thấy sự gia tăng các yếu tố gây gián đoạn trong quá trình học tập, ảnh hưởng trực tiếp đến khả năng duy trì sự tập trung.','Để xử lý mật độ mất tập trung tăng cao, cần tập trung vào việc xác định và loại bỏ các nguồn gây xao nhãng trong môi trường học tập.','["Trong phiên tiếp theo, người học sẽ chủ động tắt thông báo từ các ứng dụng không liên quan và đặt điện thoại ở chế độ im lặng trong suốt 1 giờ học để giảm thiểu gián đoạn.","Kiểm soát môi trường học tập bằng cách thông báo cho người cùng nhà về thời gian học tập để hạn chế tiếng ồn và sự làm phiền trong 1 giờ học sắp tới.","Trong phiên tiếp theo, cần đạt mức tập trung 4/5 và giảm mật độ mất tập trung xuống dưới 2 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung. Nếu mật độ mất tập trung tăng lên trên 4.00 lần/giờ trong phiên tiếp theo thì cần tạm dừng phiên học.','','2026-04-18 13:48:37','gemini-2.5-flash-lite','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(54,32,112,'2026-04-18','High Risk','["Mức tập trung 1/5 ở phiên hiện tại giảm từ 3/5 ở 2 phiên trước đó (S6, S7).","Mức muốn bỏ cuộc 5/5 ở phiên hiện tại tăng đột biến từ 2/5 ở 3 phiên trước đó (S5, S6, S7).","Số giờ học 24h ở phiên hiện tại cao bất thường so với 2h ở phiên S7 và 0.75h ở phiên S6, trong khi mức tập trung lại giảm xuống 1/5."]','Nếu mức muốn bỏ cuộc tiếp tục ở mức 5/5, tín hiệu Mức tập trung 1/5 ở phiên hiện tại có khả năng giảm sâu hơn nữa hoặc duy trì ở mức thấp. Nếu người học thực hiện nghỉ ngơi đầy đủ và giảm áp lực học tập, mức muốn bỏ cuộc có khả năng giảm về 2/5.','Tín hiệu Mức muốn bỏ cuộc 5/5 ở phiên hiện tại tăng đột biến từ 2/5 ở 3 phiên trước đó (S5, S6, S7) cho thấy sự suy giảm ý chí nghiêm trọng, là nguyên nhân gốc dẫn đến việc học không hiệu quả và mất tập trung.','Để xử lý mức muốn bỏ cuộc tăng đột biến, cần tập trung vào việc giảm thiểu các yếu tố gây căng thẳng và phục hồi năng lượng cho người học.','["Người học chủ động giảm thời gian học xuống còn tối đa 1 giờ trong phiên tiếp theo, tập trung vào các nhiệm vụ ngắn và dễ hoàn thành.","Người học thực hiện các hoạt động thư giãn ngoài giờ học như nghe nhạc hoặc đi dạo trong 30 phút sau mỗi 2 giờ học để giảm căng thẳng.","Trong phiên tiếp theo, mức muốn bỏ cuộc cần giảm về 3/5 và mức tập trung cần cải thiện lên 2/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì cần tạm dừng phiên học và thực hiện các hoạt động phục hồi năng lượng ngay lập tức. Nếu mức tập trung giảm xuống dưới 1/5 trong phiên tiếp theo thì cần đánh giá lại toàn bộ kế hoạch học tập.','','2026-04-18 14:10:09','gemini-2.5-flash-lite','May');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(55,32,113,'2026-04-18','Fluctuating','["Mức tập trung tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.00 lần/giờ.","Mức muốn bỏ cuộc giảm đột ngột từ 5/5 ở phiên trước xuống 1/5 ở phiên hiện tại, cùng với việc đạt mục tiêu.","Số giờ học giảm từ 24h ở phiên trước xuống 1h ở phiên hiện tại, trong khi mức tập trung tăng từ 1/5 lên 4/5."]','Nếu tín hiệu Mức tập trung tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.00 lần/giờ. không thay đổi, mức tập trung có khả năng duy trì ở mức cao trong phiên tiếp theo. Nếu việc giảm số lần mất tập trung được duy trì, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.00 lần/giờ. cho thấy sự phục hồi đột ngột sau giai đoạn tập trung thấp kéo dài, có thể do yếu tố bên ngoài hoặc thay đổi đột ngột trong phiên học.','Để xử lý tín hiệu Mức tập trung tăng từ 1/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.00 lần/giờ., cần xác định và duy trì các yếu tố đã góp phần vào sự cải thiện đột ngột này, đồng thời đảm bảo môi trường học tập không có yếu tố gây xao nhãng.','["Thực hiện phiên học tiếp theo với thời lượng 1h, tập trung vào việc duy trì môi trường yên tĩnh, không có thiết bị điện tử không cần thiết, trong 1 giờ.","Trong phiên học tiếp theo, ghi nhận lại các yếu tố môi trường và hành vi cá nhân có thể đã góp phần vào sự gia tăng mức tập trung và giảm mất tập trung.","Trong phiên học tiếp theo, đạt mức tập trung 4/5 và số lần mất tập trung dưới 1 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần xem xét lại các yếu tố môi trường học tập. Nếu số lần mất tập trung tăng lên 2 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại.','','2026-04-18 14:11:09','gemini-2.5-flash-lite','June');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(56,32,114,'2026-04-18','Stable','["Mức tập trung tăng từ 4/5 ở phiên trước lên 5/5 ở phiên hiện tại, trong khi số giờ học giữ nguyên 1h.","Mức muốn bỏ cuộc giảm từ 1/5 ở phiên trước xuống 1/5 ở phiên hiện tại, sau khi có giai đoạn tăng đột biến lên 5/5 ở phiên -2.","Mức tập trung có xu hướng tăng dần trong 3 phiên gần nhất (1/5 → 4/5 → 5/5) sau giai đoạn giảm sâu ở các phiên trước đó."]','Nếu tín hiệu Mức tập trung tăng từ 4/5 ở phiên trước lên 5/5 ở phiên hiện tại, trong khi số giờ học giữ nguyên 1h. không thay đổi, mức tập trung cao có khả năng được duy trì trong phiên tiếp theo. Nếu áp dụng biện pháp giảm thiểu yếu tố gây mất tập trung, mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung tăng từ 4/5 ở phiên trước lên 5/5 ở phiên hiện tại, trong khi số giờ học giữ nguyên 1h. cho thấy sự cải thiện đột ngột về khả năng duy trì sự chú ý, có thể do yếu tố bên ngoài hoặc sự điều chỉnh chiến lược học tập không rõ ràng.','Để xử lý sự cải thiện đột ngột về khả năng duy trì sự chú ý, cần xác định và củng cố các yếu tố đã góp phần vào sự thay đổi tích cực này, đồng thời đảm bảo môi trường học tập không bị gián đoạn.','["Trong phiên tiếp theo (trong vòng 24h), người học cần duy trì thời gian học 1h và chủ động loại bỏ mọi yếu tố có thể gây xao nhãng để giữ vững mức tập trung 5/5.","Kiểm soát môi trường học tập bằng cách thông báo cho người xung quanh về thời gian học tập để hạn chế tối đa sự làm phiền, đảm bảo mật độ mất tập trung dưới 0.5 lần/giờ.","Trong phiên tiếp theo, cần đạt mức tập trung 5/5 và mức muốn bỏ cuộc 1/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần xem xét lại các yếu tố môi trường. Nếu mức muốn bỏ cuộc tăng lên 2/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược học tập.','','2026-04-18 14:14:31','gemini-2.5-flash-lite','July');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(57,32,115,'2026-04-18','Fluctuating','["Số giờ học giảm từ 1h ở phiên trước xuống 0.5h ở phiên hiện tại trong khi mức tập trung duy trì ở mức 5/5.","Trạng thái căng thẳng xuất hiện đồng thời với việc không đạt mục tiêu học tập dù mức tập trung đạt 5/5."]','Nếu số giờ học không thay đổi, tín hiệu số giờ học giảm từ 1h xuống 0.5h có khả năng dẫn đến việc tiếp tục không đạt mục tiêu trong các phiên tới. Nếu thời gian học được điều chỉnh tăng lên 1h, chỉ số đạt mục tiêu có khả năng cải thiện về trạng thái đạt.','Tín hiệu số giờ học giảm từ 1h xuống 0.5h cho thấy sự mất cân bằng giữa cường độ tập trung cao và khối lượng công việc thực tế, dẫn đến việc không đạt mục tiêu.','Để xử lý số giờ học giảm từ 1h xuống 0.5h, cần thiết lập khung thời gian học cố định để đảm bảo khối lượng công việc hoàn thành mà không gây ra trạng thái căng thẳng.','["Thiết lập lịch học cố định 1h cho phiên tiếp theo để bù đắp khối lượng công việc thiếu hụt.","Điều chỉnh nội dung học tập trong 1h đó thành các phần nhỏ hơn để duy trì mức tập trung 5/5 mà không gây căng thẳng.","Đo lại chỉ số đạt mục tiêu trong phiên tiếp theo để xác nhận việc hoàn thành 1h học có giúp chuyển trạng thái từ không đạt sang đạt hay không."]','Nếu số giờ học đạt 1h trong phiên tiếp theo thì duy trì lịch trình này; nếu mức tập trung giảm xuống dưới 5/5 thì giảm khối lượng nội dung học tập trong 1h đó.','','2026-04-18 14:16:00','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(58,32,116,'2026-04-18','Stable','["Mức tập trung đạt 5/5 trong 3 phiên liên tiếp (S10, S11, S12) đi kèm với mật độ mất tập trung 0.00 lần/giờ.","Mức muốn bỏ cuộc duy trì ổn định ở mức 1/5 trong 4 phiên gần nhất (S9, S10, S11, S12) dù số giờ học biến động từ 0.5h đến 24h."]','Nếu tín hiệu mức tập trung đạt 5/5 không thay đổi, khả năng duy trì mục tiêu học tập trong các phiên tiếp theo là rất cao. Nếu thời lượng học tập được điều chỉnh về mức trung bình 1-2 giờ/phiên, chỉ số mức muốn bỏ cuộc có khả năng duy trì ổn định ở mức 1/5.','Tín hiệu mức tập trung đạt 5/5 trong 3 phiên liên tiếp cho thấy sự ổn định trong khả năng duy trì cường độ học tập cao mà không bị gián đoạn bởi các yếu tố ngoại cảnh.','Để xử lý tín hiệu mức tập trung đạt 5/5, cần thiết lập cơ chế duy trì nhịp độ học tập ổn định thông qua việc phân bổ thời gian học tập đều đặn thay vì dồn khối lượng lớn vào một phiên.','["Thiết lập lịch học cố định 1.5 giờ mỗi phiên trong 48 giờ tới để tránh quá tải so với phiên 24 giờ hiện tại.","Duy trì môi trường học tập không có yếu tố gây mất tập trung như đã ghi nhận trong 3 phiên gần nhất.","Đo lại chỉ số mức tập trung và mức muốn bỏ cuộc sau mỗi phiên, yêu cầu mức tập trung đạt tối thiểu 4/5 để xác nhận hiệu quả duy trì."]','Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì thực hiện giảm thời lượng học tập xuống 0.5 giờ. Nếu mức muốn bỏ cuộc tăng lên trên 2/5 thì thực hiện nghỉ giải lao 10 phút sau mỗi 30 phút học.','','2026-04-18 14:17:53','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(60,33,118,'2026-04-18','Fluctuating','["Mức tập trung 3/5 đi kèm với 3 lần mất tập trung trong 3 giờ học","Mật độ mất tập trung 1.00 lần/giờ xuất hiện cùng với yếu tố gây mất tập trung là điện thoại"]','Nếu yếu tố gây mất tập trung là điện thoại không thay đổi, tín hiệu mật độ mất tập trung 1.00 lần/giờ có khả năng duy trì hoặc tăng lên trong các phiên tiếp theo. Nếu hành động cách ly điện thoại được thực hiện, mức tập trung có khả năng cải thiện lên mức 4/5.','Tín hiệu mật độ mất tập trung 1.00 lần/giờ xuất hiện cùng với yếu tố gây mất tập trung là điện thoại cho thấy đây là nguyên nhân gốc rễ vì sự hiện diện của thiết bị tạo ra các gián đoạn định kỳ trong quá trình học tập.','Để xử lý yếu tố gây mất tập trung là điện thoại, cơ chế tác động sẽ là thiết lập rào cản vật lý bằng cách di chuyển thiết bị ra khỏi không gian học tập trong suốt thời gian thực hiện nhiệm vụ.','["Di chuyển điện thoại sang phòng khác trong toàn bộ 3 giờ học của phiên tiếp theo để loại bỏ yếu tố gây mất tập trung.","Đặt điện thoại ở chế độ im lặng và để ngoài tầm với trong suốt thời gian học tập để kiểm soát môi trường.","Đo lại số lần mất tập trung trong phiên tiếp theo, mục tiêu cần đạt là dưới 1 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu số lần mất tập trung đạt mức 2 lần/giờ trong phiên tiếp theo thì thực hiện kiểm tra lại vị trí đặt điện thoại; nếu mức tập trung đạt 4/5 thì duy trì quy trình cách ly thiết bị.','','2026-04-18 14:35:50','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(61,33,119,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 3/5 xuống 2/5 trong khi số giờ học tăng từ 3h lên 4h.","Mức muốn bỏ cuộc tăng từ 2/5 lên 3/5 đi kèm với 5 lần mất tập trung do yếu tố lo lắng."]','Nếu mức muốn bỏ cuộc tăng từ 2/5 lên 3/5 không thay đổi, tín hiệu mức tập trung giảm từ 3/5 xuống 2/5 có khả năng tiếp tục duy trì ở mức thấp. Nếu thời gian học mỗi phiên được điều chỉnh giảm xuống dưới 3h, mức tập trung có khả năng cải thiện về mức 3/5.','Tín hiệu mức muốn bỏ cuộc tăng từ 2/5 lên 3/5 đi kèm với 5 lần mất tập trung do yếu tố lo lắng cho thấy sự quá tải trong thời gian học kéo dài là nguyên nhân gốc rễ dẫn đến suy giảm khả năng duy trì sự tập trung.','Để xử lý mức muốn bỏ cuộc tăng từ 2/5 lên 3/5 đi kèm với 5 lần mất tập trung do yếu tố lo lắng, cần áp dụng cơ chế chia nhỏ thời gian học thành các block 45 phút kèm nghỉ giải lao để giảm áp lực tâm lý và duy trì sự tập trung.','["Chia nhỏ thời gian học thành 4 block, mỗi block 45 phút và nghỉ 10 phút giữa các block trong phiên tiếp theo.","Loại bỏ các yếu tố gây lo lắng bằng cách tắt thông báo thiết bị và chỉ để tài liệu cần thiết trên bàn học trong suốt 45 phút học tập.","Đo lại mức tập trung vào cuối phiên tiếp theo, mục tiêu đạt mức 3/5 để xác nhận hiệu quả của việc chia nhỏ thời gian."]','Nếu mức tập trung đạt 3/5 trong phiên tiếp theo thì duy trì cấu trúc block 45 phút; nếu mức muốn bỏ cuộc vẫn ở mức 3/5 thì giảm tổng thời gian học xuống còn 2h.','','2026-04-18 14:38:46','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(62,33,120,'2026-04-18','Fluctuating','["Mức tập trung 4/5 trong phiên hiện tại tăng từ 2/5 ở phiên trước nhưng không đạt mục tiêu học tập.","Số lần mất tập trung 3 lần (mật độ 1.00 lần/giờ) duy trì ổn định so với phiên -2 dù thời gian học giảm từ 4h xuống 3h."]','Nếu tín hiệu mức tập trung 4/5 không đạt mục tiêu không thay đổi, việc duy trì mật độ mất tập trung 1.00 lần/giờ có khả năng dẫn đến việc không hoàn thành mục tiêu trong các phiên tiếp theo. Nếu việc lập kế hoạch khối lượng kiến thức theo giờ được thực hiện, chỉ số đạt mục tiêu có khả năng cải thiện về trạng thái đạt.','Tín hiệu mức tập trung 4/5 không đạt mục tiêu cho thấy sự thiếu hụt trong việc phân bổ thời gian thực tế so với khối lượng kiến thức cần hoàn thành.','Để xử lý tín hiệu mức tập trung 4/5 không đạt mục tiêu, cần áp dụng cơ chế chia nhỏ khối lượng kiến thức theo khung thời gian 60 phút để đảm bảo mục tiêu được hoàn thành trong mỗi phiên.','["Chia nhỏ khối lượng kiến thức thành 3 phần tương ứng với 3 giờ học, thực hiện kiểm tra tiến độ sau mỗi 60 phút.","Thiết lập bộ đếm thời gian 60 phút cho mỗi phần kiến thức để kiểm soát mật độ mất tập trung không vượt quá 1.00 lần/giờ.","Đo lại chỉ số đạt mục tiêu trong phiên tiếp theo để xác nhận việc hoàn thành 100% khối lượng kiến thức đã chia nhỏ."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì thực hiện rà soát lại khối lượng kiến thức; nếu số lần mất tập trung vượt quá 1.00 lần/giờ thì thực hiện điều chỉnh thời gian nghỉ giữa các phần kiến thức.','','2026-04-18 14:43:46','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(63,18,117,'2026-04-18','Fluctuating','["Mật độ mất tập trung giảm từ 4.00 lần/giờ ở phiên trước xuống 0.50 lần/giờ ở phiên hiện tại","Số giờ học tăng từ 1h ở phiên trước lên 4h ở phiên hiện tại trong khi mức tập trung duy trì ở 3/5"]','Nếu mật độ mất tập trung giảm từ 4.00 lần/giờ ở phiên trước xuống 0.50 lần/giờ ở phiên hiện tại không duy trì ổn định, mức tập trung 3/5 có khả năng quay lại ngưỡng 2/5. Nếu hành động kiểm soát thời gian học được thực hiện, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mật độ mất tập trung giảm từ 4.00 lần/giờ ở phiên trước xuống 0.50 lần/giờ ở phiên hiện tại cho thấy sự thay đổi đột ngột trong khả năng duy trì sự chú ý liên tục, đây là nguyên nhân gốc rễ dẫn đến sự biến động của mức tập trung.','Để xử lý mật độ mất tập trung giảm từ 4.00 lần/giờ ở phiên trước xuống 0.50 lần/giờ ở phiên hiện tại, cần thiết lập cơ chế chia nhỏ thời gian học thành các block 60 phút kèm nghỉ giải lao cố định để ổn định nhịp độ học tập.','["Chia nhỏ 4 giờ học thành 4 block, mỗi block 60 phút với 5 phút nghỉ giữa các block trong phiên tiếp theo.","Loại bỏ các thiết bị điện tử không liên quan trong phạm vi 2 mét tại khu vực học tập trong 48 giờ tới.","Đo lại mật độ mất tập trung, chỉ số cần đạt dưới 0.50 lần/giờ ở phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mật độ mất tập trung đạt trên 1.00 lần/giờ trong phiên tiếp theo thì thực hiện giảm thời gian học mỗi block xuống 45 phút. Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 60 phút.','','2026-04-18 15:23:04','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(64,18,101,'2026-04-18','Fluctuating','["Mức tập trung 3/5 duy trì ổn định trong 3 phiên gần nhất nhưng thấp hơn mức 4/5 ở các phiên cũ.","Số lần mất tập trung 5 lần (mật độ 1.67 lần/giờ) xuất hiện cùng yếu tố đau bụng, cao hơn mức 0.5 lần/giờ ở phiên trước đó."]','Nếu yếu tố đau bụng không thay đổi, tín hiệu số lần mất tập trung 5 lần có khả năng duy trì mật độ cao, khiến mức tập trung không thể quay lại ngưỡng 4/5. Nếu chế độ nghỉ ngơi được thực hiện, mật độ mất tập trung có khả năng cải thiện về mức dưới 1 lần/giờ.','Tín hiệu số lần mất tập trung 5 lần (mật độ 1.67 lần/giờ) kèm yếu tố đau bụng cho thấy đây là nguyên nhân gốc rễ gây gián đoạn quá trình học tập, làm giảm mức tập trung từ 4/5 xuống 3/5.','Để xử lý yếu tố đau bụng, cần thiết lập cơ chế điều chỉnh thời gian học tập theo chu kỳ nghỉ ngơi ngắn để giảm áp lực thể chất.','["Thực hiện nghỉ giải lao 5 phút sau mỗi 45 phút học tập trong 48 giờ tới để giảm áp lực thể chất.","Loại bỏ các yếu tố gây đau bụng bằng cách điều chỉnh thời gian ăn uống cách giờ học ít nhất 60 phút.","Đo lại mật độ mất tập trung trong phiên tiếp theo, mục tiêu đạt mức dưới 1 lần/giờ để xác nhận hiệu quả."]','Nếu mật độ mất tập trung đạt trên 1.5 lần/giờ trong phiên tiếp theo thì thực hiện dừng phiên học ngay lập tức để kiểm tra sức khỏe; nếu mức tập trung đạt 4/5 thì duy trì lịch trình học tập hiện tại.','','2026-04-18 15:24:04','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(65,33,121,'2026-04-18','Fluctuating','["Mức tập trung dao động từ 2/5 ở phiên -2 lên 4/5 ở phiên -1 và giảm xuống 3/5 ở phiên hiện tại","Mật độ mất tập trung giảm từ 1.25 lần/giờ ở phiên -2 xuống 0.75 lần/giờ ở phiên hiện tại"]','Nếu mức tập trung dao động không được ổn định, tín hiệu mức tập trung 3/5 có khả năng tiếp tục giảm xuống dưới 3/5 trong phiên tiếp theo. Nếu thời gian học được cố định ở mức 3 giờ, chỉ số tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung dao động từ 2/5 lên 4/5 rồi về 3/5 cho thấy sự thiếu ổn định trong duy trì cường độ học tập, là nguyên nhân gốc dẫn đến việc không đạt mục tiêu ở phiên -1.','Để xử lý sự thiếu ổn định trong duy trì cường độ học tập, cần thiết lập khung thời gian học cố định 3 giờ mỗi phiên để giảm tải áp lực duy trì sự tập trung kéo dài.','["Thiết lập lịch học cố định 3 giờ mỗi phiên trong 48 giờ tới để ổn định nhịp độ học tập.","Giới hạn thời gian học liên tục trong 90 phút mỗi block để kiểm soát mật độ mất tập trung dưới 0.75 lần/giờ.","Đo lại mức tập trung vào phiên tiếp theo, yêu cầu đạt mức 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt dưới 3/5 trong phiên tiếp theo thì thực hiện giảm thời gian học xuống 2 giờ; nếu mật độ mất tập trung vượt quá 1.00 lần/giờ thì thực hiện chia nhỏ phiên học thành 2 block 1.5 giờ.','','2026-04-18 15:26:03','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(66,32,111,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 1/5 ở phiên hiện tại","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 2/5 ở phiên hiện tại đi kèm với mật độ mất tập trung 2.50 lần/giờ"]','Nếu mức tập trung 1/5 không thay đổi, tín hiệu mức muốn bỏ cuộc 2/5 có khả năng tiếp tục tăng lên mức 3/5. Nếu thời gian học được chia nhỏ thành các block 30 phút, mức tập trung có khả năng cải thiện về mức 3/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 1/5 cho thấy sự sụt giảm đột ngột trong khả năng duy trì trạng thái học tập, là nguyên nhân gốc dẫn đến việc tăng mức muốn bỏ cuộc và mật độ mất tập trung.','Để xử lý mức tập trung 1/5, áp dụng cơ chế chia nhỏ thời gian học thành các block 30 phút kèm nghỉ giải lao ngắn để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia nhỏ thời gian học thành các block 30 phút trong 48 giờ tới để giảm áp lực duy trì sự chú ý.","Thiết lập môi trường học tập không thiết bị gây nhiễu trong mỗi block 30 phút để kiểm soát mật độ mất tập trung 2.50 lần/giờ.","Đo lại mức tập trung vào phiên tiếp theo, mục tiêu đạt mức 3/5 để xác nhận hiệu quả của việc chia nhỏ thời gian."]','Nếu mức tập trung đạt 3/5 trong phiên tiếp theo thì duy trì phương pháp chia nhỏ thời gian; nếu mức tập trung vẫn ở mức 1/5 thì giảm thời gian học mỗi block xuống còn 20 phút.','','2026-04-18 15:27:58','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(67,32,111,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 1/5 trong phiên hiện tại","Mật độ mất tập trung đạt 2.50 lần/giờ trong khi phiên trước là 0.00 lần/giờ"]','Nếu mức tập trung 1/5 không thay đổi, tín hiệu mật độ mất tập trung 2.50 lần/giờ có khả năng duy trì ở mức cao trong phiên tiếp theo. Nếu thời gian học mỗi phiên được điều chỉnh về mức 0.5h - 1h, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 1/5 cho thấy sự sụt giảm đột ngột trong khả năng duy trì sự chú ý, đây là nguyên nhân gốc dẫn đến việc tăng mật độ mất tập trung lên 2.50 lần/giờ.','Để xử lý mức tập trung 1/5, cần áp dụng cơ chế chia nhỏ thời gian học thành các block 30 phút kèm nghỉ giải lao cố định để giảm tải áp lực duy trì sự chú ý.','["Chia nhỏ thời gian học thành 2 block, mỗi block 30 phút, nghỉ 5 phút giữa các block trong phiên tiếp theo.","Loại bỏ các thiết bị điện tử không liên quan khỏi bàn học trong suốt 60 phút học tập để kiểm soát mật độ mất tập trung.","Đo lại mức tập trung vào cuối phiên tiếp theo, mục tiêu đạt mức 4/5 để xác nhận hiệu quả của việc chia nhỏ block thời gian."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 30 phút; nếu mức tập trung vẫn ở mức 1/5 thì giảm thời gian học xuống còn 0.5h/phiên.','','2026-04-18 15:27:58','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(68,32,110,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 trong phiên hiện tại","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 2/5 trong phiên hiện tại"]','Nếu mức tập trung giảm từ 5/5 xuống 3/5 không thay đổi, tín hiệu mức muốn bỏ cuộc có khả năng tiếp tục tăng từ 2/5 lên mức cao hơn. Nếu thời gian học được giới hạn cố định ở mức 0.75h, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 3/5 cho thấy sự suy giảm khả năng duy trì trạng thái học tập ổn định, là nguyên nhân gốc dẫn đến sự gia tăng mức muốn bỏ cuộc.','Để xử lý mức tập trung giảm từ 5/5 xuống 3/5, cần thiết lập cấu trúc phiên học ngắn hạn với thời lượng cố định để giảm tải áp lực nhận thức.','["Giới hạn thời gian học mỗi phiên trong 48 giờ tới ở mức 0.75 giờ để duy trì sự ổn định.","Loại bỏ các yếu tố gây xao nhãng trong không gian học tập trước khi bắt đầu phiên để đảm bảo mức tập trung không giảm dưới 3/5.","Đo lại mức tập trung vào phiên tiếp theo, yêu cầu đạt mức 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì thời lượng 0.75 giờ; nếu mức tập trung đạt 2/5 thì giảm thời lượng học xuống 0.5 giờ.','','2026-04-18 15:28:47','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(69,32,108,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 2/5 trong phiên hiện tại","Số lần mất tập trung tăng từ 0 lần/giờ ở 3 phiên gần nhất lên 2.50 lần/giờ ở phiên hiện tại","Mức muốn bỏ cuộc tăng từ 1/5 ở 3 phiên gần nhất lên 2/5 trong phiên hiện tại"]','Nếu mức tập trung giảm từ 5/5 ở phiên trước xuống 2/5 trong phiên hiện tại không thay đổi, số lần mất tập trung có khả năng duy trì ở mức cao hơn 2.00 lần/giờ. Nếu thời gian học mỗi phiên được rút ngắn xuống dưới 1 giờ, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung giảm từ 5/5 ở phiên trước xuống 2/5 trong phiên hiện tại cho thấy sự đứt gãy trong khả năng duy trì trạng thái học tập ổn định, dẫn đến việc tăng mật độ mất tập trung và mức muốn bỏ cuộc.','Để xử lý mức tập trung giảm từ 5/5 ở phiên trước xuống 2/5 trong phiên hiện tại, cần áp dụng cơ chế chia nhỏ thời gian học thành các block 30 phút để giảm tải áp lực duy trì sự tập trung liên tục.','["Chia nhỏ thời gian học thành các block 30 phút trong 48 giờ tới để giảm áp lực duy trì sự tập trung.","Loại bỏ các thiết bị điện tử không liên quan trong 30 phút mỗi block để kiểm soát mật độ mất tập trung.","Đo lại mức tập trung vào phiên tiếp theo, mục tiêu đạt mức 4/5 để xác nhận hiệu quả của việc chia nhỏ thời gian."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 30 phút; nếu mức tập trung vẫn ở mức 2/5 thì giảm thời gian học mỗi block xuống còn 20 phút.','','2026-04-18 15:28:58','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(70,32,107,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở 3 phiên trước xuống 3/5 tại phiên hiện tại","Số giờ học tăng lên 3 giờ so với mức trung bình 8.5 giờ của 3 phiên trước đi kèm với mật độ mất tập trung 1.00 lần/giờ"]','Nếu thời lượng học tập 3 giờ không thay đổi, tín hiệu mức tập trung 3/5 có khả năng tiếp tục duy trì ở mức thấp hoặc giảm thêm. Nếu thời lượng học tập được điều chỉnh về mức 1-2 giờ, chỉ số mức tập trung có khả năng cải thiện về mức 4/5 hoặc 5/5.','Tín hiệu số giờ học tăng lên 3 giờ đi kèm mật độ mất tập trung 1.00 lần/giờ cho thấy sự quá tải trong thời lượng học tập dẫn đến suy giảm khả năng duy trì sự tập trung.','Để xử lý thời lượng học tập quá tải, cần áp dụng cơ chế chia nhỏ phiên học theo phương pháp Pomodoro để kiểm soát mật độ mất tập trung.','["Chia nhỏ 3 giờ học thành 4 phiên, mỗi phiên 45 phút kèm 15 phút nghỉ giải lao cố định trong 48 giờ tới.","Loại bỏ các thiết bị điện tử không liên quan trong 45 phút học tập để kiểm soát mật độ mất tập trung về mức 0.00 lần/giờ.","Đo lại mức tập trung vào phiên tiếp theo, chỉ số cần đạt tối thiểu 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc phiên 45 phút; nếu mức tập trung vẫn ở mức 3/5 thì giảm thời lượng phiên học xuống còn 30 phút.','','2026-04-18 15:29:48','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(71,32,106,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 ở phiên hiện tại.","Số lần mất tập trung tăng từ 0 lần/giờ ở 3 phiên gần nhất lên 1.00 lần/giờ ở phiên hiện tại."]','Nếu mức tập trung giảm từ 5/5 xuống 3/5 không thay đổi, số lần mất tập trung có khả năng duy trì ở mức 1.00 lần/giờ hoặc cao hơn. Nếu thời gian học mỗi phiên được điều chỉnh về mức dưới 2 giờ, mức tập trung có khả năng cải thiện về mức 5/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 3/5 cho thấy sự suy giảm khả năng duy trì trạng thái học tập ổn định so với chuỗi 3 phiên trước đó.','Để xử lý mức tập trung giảm từ 5/5 xuống 3/5, cần áp dụng cơ chế phân đoạn thời gian học tập thành các khối ngắn để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia nhỏ thời gian học thành các block 45 phút mỗi block trong 48 giờ tới.","Loại bỏ các thiết bị điện tử không phục vụ việc học trong phạm vi 2 mét tại khu vực học tập.","Đo lại mức tập trung vào phiên tiếp theo để xác nhận đạt mức 4/5 hoặc 5/5."]','Nếu mức tập trung đạt 5/5 trong phiên tiếp theo thì duy trì cấu trúc block 45 phút; nếu mức tập trung vẫn ở mức 3/5 thì giảm thời gian học mỗi block xuống 30 phút.','','2026-04-18 15:30:16','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(72,33,126,'2026-04-18','Fluctuating','["Mức tập trung 3/5 tại phiên hiện tại không thay đổi so với phiên -1 nhưng số giờ học giảm từ 4h xuống 1.25h.","Mật độ mất tập trung tăng từ 0.75 lần/giờ ở phiên -1 lên 1.60 lần/giờ ở phiên hiện tại."]','Nếu mật độ mất tập trung 1.60 lần/giờ không thay đổi, số giờ học có khả năng tiếp tục duy trì ở mức thấp dưới 2h mỗi phiên. Nếu thời gian nghỉ giải lao được cố định sau mỗi 45 phút học, mật độ mất tập trung có khả năng cải thiện về mức dưới 1.00 lần/giờ.','Tín hiệu mật độ mất tập trung tăng từ 0.75 lần/giờ lên 1.60 lần/giờ cho thấy sự suy giảm khả năng duy trì trạng thái học tập liên tục, dẫn đến việc rút ngắn thời gian học thực tế.','Để xử lý mật độ mất tập trung tăng cao, cần áp dụng cơ chế chia nhỏ phiên học thành các block 45 phút kèm thời gian nghỉ cố định để tái tạo khả năng tập trung.','["Thiết lập bộ đếm thời gian 45 phút cho mỗi block học trong 48 giờ tới để kiểm soát mật độ mất tập trung.","Loại bỏ các thiết bị điện tử không phục vụ việc học trong phạm vi bàn học để giảm thiểu các tác nhân gây gián đoạn.","Đo lại mật độ mất tập trung vào phiên tiếp theo, mục tiêu đạt mức dưới 1.00 lần/giờ để xác nhận hiệu quả can thiệp."]','Nếu mật độ mất tập trung đạt mức trên 1.50 lần/giờ trong phiên tiếp theo thì thực hiện rút ngắn block học xuống 30 phút. Nếu số giờ học đạt trên 2h trong phiên tiếp theo thì duy trì cấu trúc block 45 phút hiện tại.','','2026-04-18 15:50:54','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(73,33,128,'2026-04-18','Fluctuating','["Mật độ mất tập trung giảm xuống 0.33 lần/giờ trong phiên hiện tại so với mức 1.60 lần/giờ ở phiên -1","Sự xuất hiện của điện thoại là yếu tố gây mất tập trung duy nhất trong phiên hiện tại dù mức tập trung đạt 4/5"]','Nếu sự xuất hiện của điện thoại không thay đổi, tín hiệu mật độ mất tập trung có khả năng tăng trở lại mức trên 1.00 lần/giờ. Nếu việc cách ly điện thoại được thực hiện, mức tập trung có khả năng duy trì ổn định ở mức 4/5.','Tín hiệu sự xuất hiện của điện thoại là yếu tố gây mất tập trung duy nhất cho thấy thiết bị này là rào cản tiềm ẩn đối với sự ổn định của mức tập trung trong các phiên tới.','Để xử lý sự xuất hiện của điện thoại, cần thiết lập cơ chế cách ly vật lý thiết bị khỏi không gian học tập trong suốt thời gian diễn ra phiên học.','["Di chuyển điện thoại sang phòng khác hoặc tủ khóa trong toàn bộ 3 giờ học của phiên tiếp theo.","Đặt thông báo nhắc nhở về việc cách ly thiết bị trước 5 phút khi bắt đầu phiên học để kiểm soát môi trường.","Đo lại mật độ mất tập trung trong phiên tiếp theo, mục tiêu đạt mức 0 lần/giờ để xác nhận hiệu quả can thiệp."]','Nếu mật độ mất tập trung đạt ngưỡng 0.5 lần/giờ trong phiên tiếp theo thì thực hiện kiểm tra lại vị trí đặt điện thoại; nếu mức tập trung giảm xuống dưới 3/5 thì thực hiện đánh giá lại thời lượng học.','','2026-04-18 15:52:52','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(74,33,129,'2026-04-18','Stable','["Mức tập trung duy trì ở mức 4/5 trong 2 phiên liên tiếp, đi kèm với số lần mất tập trung giảm từ 1.60 lần/giờ ở phiên -2 xuống 0.67 lần/giờ ở phiên hiện tại.","Yếu tố gây mất tập trung là đói xuất hiện trong phiên hiện tại với 2 lần mất tập trung, dù mức tập trung vẫn đạt 4/5."]','Nếu yếu tố gây mất tập trung là đói không thay đổi, tín hiệu 2 lần mất tập trung trong phiên hiện tại có khả năng tái diễn hoặc tăng lên trong các phiên tiếp theo. Nếu việc bổ sung dinh dưỡng trước phiên học được thực hiện, số lần mất tập trung có khả năng giảm về mức dưới 0.5 lần/giờ.','Tín hiệu yếu tố gây mất tập trung là đói cho thấy đây là nguyên nhân gốc rễ gây ra 2 lần mất tập trung trong phiên hiện tại, làm gián đoạn quá trình học tập dù mức tập trung tổng thể đang ổn định.','Để xử lý yếu tố gây mất tập trung là đói, cần thiết lập cơ chế nạp năng lượng cố định trước khi bắt đầu phiên học để loại bỏ nhu cầu ăn uống trong thời gian học.','["Thực hiện ăn nhẹ trước khi bắt đầu phiên học 15 phút trong 2 phiên tiếp theo để loại bỏ yếu tố đói.","Kiểm soát môi trường học tập bằng cách không để thực phẩm hoặc đồ ăn trong khu vực học để tránh kích thích nhu cầu ăn uống.","Đo lại số lần mất tập trung trong phiên tiếp theo, mục tiêu đạt mức dưới 0.5 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu số lần mất tập trung đạt ngưỡng 1 lần/giờ trong phiên tiếp theo thì thực hiện điều chỉnh thời gian ăn nhẹ sớm hơn 30 phút; nếu mức tập trung giảm xuống dưới 3/5 thì thực hiện đánh giá lại lịch trình học tập.','','2026-04-18 15:54:42','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(75,32,125,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 trong phiên hiện tại kèm theo 3 lần mất tập trung.","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 3/5 trong phiên hiện tại dù vẫn đạt mục tiêu học tập."]','Nếu mức tập trung giảm từ 5/5 xuống 3/5 không thay đổi, tín hiệu mức muốn bỏ cuộc có khả năng tiếp tục duy trì ở mức 3/5 hoặc cao hơn. Nếu thời gian học mỗi phiên được điều chỉnh về mức 1h, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu mức tập trung giảm từ 5/5 xuống 3/5 cho thấy sự suy giảm khả năng duy trì trạng thái học tập ổn định, dẫn đến sự gia tăng mức muốn bỏ cuộc.','Để xử lý mức tập trung giảm từ 5/5 xuống 3/5, cần áp dụng cơ chế giới hạn thời gian học tập mỗi phiên để giảm tải áp lực nhận thức.','["Giới hạn thời gian học tập tối đa 1 giờ mỗi phiên trong 48 giờ tới để ngăn chặn sự suy giảm tập trung.","Loại bỏ các tác nhân gây xao nhãng trong không gian học tập trước khi bắt đầu phiên học tiếp theo.","Đo lại mức tập trung vào phiên kế tiếp, mục tiêu đạt mức 4/5 để xác nhận hiệu quả của việc giới hạn thời gian."]','Nếu mức tập trung đạt 3/5 trong phiên tiếp theo thì thực hiện giảm thời gian học xuống 0.5h; nếu mức muốn bỏ cuộc đạt 4/5 thì tạm dừng học tập trong 24h.','','2026-04-18 15:59:51','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(76,32,131,'2026-04-18','Fluctuating','["Mức tập trung 3/5 đi kèm với mật độ mất tập trung 1.71 lần/giờ ở phiên -1, so với mức tập trung 5/5 và mật độ 0.40 lần/giờ ở phiên hiện tại.","Mức muốn bỏ cuộc 3/5 ở phiên -1 tăng từ mức 1/5 ở các phiên trước đó, trước khi quay lại mức 1/5 ở phiên hiện tại."]','Nếu mức tập trung 3/5 đi kèm với mật độ mất tập trung 1.71 lần/giờ không được kiểm soát ổn định, các phiên tiếp theo có khả năng tái diễn mức muốn bỏ cuộc 3/5. Nếu thời gian học được duy trì dưới 2 giờ mỗi phiên, chỉ số mật độ mất tập trung có khả năng cải thiện về mức dưới 0.5 lần/giờ.','Tín hiệu mức tập trung 3/5 đi kèm với mật độ mất tập trung 1.71 lần/giờ ở phiên -1 cho thấy sự thiếu ổn định trong khả năng duy trì sự chú ý là nguyên nhân gốc dẫn đến dao động của mức muốn bỏ cuộc.','Để xử lý mức tập trung 3/5 đi kèm với mật độ mất tập trung 1.71 lần/giờ, cần áp dụng cơ chế chia nhỏ thời gian học thành các block 45 phút để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia nhỏ thời gian học thành các block 45 phút, nghỉ giải lao 5 phút giữa mỗi block trong 48 giờ tới.","Loại bỏ các thiết bị điện tử không liên quan khỏi bàn học trong suốt 45 phút của mỗi block để kiểm soát mật độ mất tập trung.","Đo lại chỉ số mật độ mất tập trung vào phiên tiếp theo, mục tiêu đạt mức dưới 0.5 lần/giờ để xác nhận hiệu quả của việc chia nhỏ block."]','Nếu mật độ mất tập trung đạt ngưỡng 1.0 lần/giờ trong phiên tiếp theo thì thực hiện giảm thời gian học mỗi block xuống còn 30 phút. Nếu mức tập trung đạt 5/5 trong 2 phiên liên tiếp thì duy trì cấu trúc block 45 phút hiện tại.','','2026-04-18 16:01:03','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(77,35,144,'2026-04-18','Fluctuating','["Mức tập trung 3/5 đi kèm với 3 lần mất tập trung trong 3 giờ học","Yếu tố gây mất tập trung từ tiếng ồn karaoke xuất hiện với mật độ 1.00 lần/giờ"]','Nếu yếu tố gây mất tập trung từ tiếng ồn karaoke không thay đổi, tín hiệu mức tập trung 3/5 có khả năng duy trì ở mức thấp. Nếu phương pháp cách âm được thực hiện, mức tập trung có khả năng cải thiện lên mức 4/5.','Tín hiệu yếu tố gây mất tập trung từ tiếng ồn karaoke xuất hiện với mật độ 1.00 lần/giờ cho thấy đây là nguyên nhân gốc rễ làm gián đoạn luồng tư duy, dẫn đến mức tập trung chỉ đạt 3/5.','Để xử lý yếu tố gây mất tập trung từ tiếng ồn karaoke, cần thiết lập rào cản vật lý hoặc sử dụng thiết bị triệt tiêu âm thanh để cô lập không gian học tập khỏi nguồn ồn bên ngoài.','["Sử dụng tai nghe chống ồn chủ động trong suốt 3 giờ học tiếp theo để triệt tiêu âm thanh từ nhà hàng xóm.","Di chuyển vị trí bàn học sang phía đối diện với hướng phát ra tiếng ồn karaoke trong phiên học tới.","Đo lại số lần mất tập trung trong phiên tiếp theo, mục tiêu đạt dưới 1 lần/giờ để xác nhận hiệu quả can thiệp."]','Nếu số lần mất tập trung đạt ngưỡng 0 lần/giờ trong phiên tiếp theo thì duy trì vị trí học mới; nếu vẫn ở mức 1.00 lần/giờ thì chuyển sang sử dụng phòng học kín hoàn toàn.','','2026-04-18 16:21:17','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(78,35,145,'2026-04-18','Stable','["Mức tập trung tăng từ 3/5 lên 5/5 đi kèm với việc giảm thời gian học từ 3h xuống 4h trong phiên hiện tại","Mức muốn bỏ cuộc giảm từ 2/5 xuống 1/5 tương ứng với việc mật độ mất tập trung giảm từ 1.00 lần/giờ xuống 0.75 lần/giờ"]','Nếu mật độ mất tập trung không thay đổi, tín hiệu mức tập trung 5/5 có khả năng duy trì ổn định. Nếu thời gian học được điều chỉnh tăng thêm 0.5h, mức tập trung có khả năng duy trì ở mức 4/5 đến 5/5.','Tín hiệu mật độ mất tập trung giảm từ 1.00 lần/giờ xuống 0.75 lần/giờ cho thấy đây là nguyên nhân gốc rễ giúp ổn định mức tập trung và giảm ý muốn bỏ cuộc.','Để xử lý mật độ mất tập trung, cần thiết lập quy trình ngắt quãng học tập chủ động để duy trì sự ổn định của chỉ số tập trung.','["Thiết lập chu kỳ học 50 phút nghỉ 10 phút trong phiên tiếp theo để duy trì mật độ mất tập trung dưới 0.75 lần/giờ","Ghi chép lại các yếu tố gây mất tập trung phát sinh trong 48 giờ tới để kiểm soát môi trường học tập","Đo lại chỉ số mật độ mất tập trung trong phiên tiếp theo để xác nhận duy trì ở mức dưới 0.75 lần/giờ"]','Nếu mật độ mất tập trung đạt ngưỡng 1.00 lần/giờ trong phiên tiếp theo thì thực hiện lại quy trình ngắt quãng 50/10. Nếu mức tập trung giảm xuống dưới 4/5 thì thực hiện rà soát lại mục tiêu học tập.','','2026-04-18 16:38:22','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(79,35,146,'2026-04-18','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 ở phiên hiện tại, đi kèm với việc đạt mục tiêu học tập.","Mức muốn bỏ cuộc tăng từ 1/5 lên 2/5 trong khi xuất hiện 2 lần mất tập trung do yếu tố ngoại cảnh (gọi điện thoại và đi mua đồ cho mẹ)."]','Nếu yếu tố gây mất tập trung (gọi điện thoại và đi mua đồ cho mẹ) không thay đổi, mức tập trung 3/5 có khả năng tiếp tục duy trì ở mức thấp hoặc giảm thêm. Nếu việc thiết lập khung giờ học cố định không bị gián đoạn được thực hiện, mức tập trung có khả năng cải thiện về mức 4/5 hoặc 5/5.','Tín hiệu về yếu tố gây mất tập trung (gọi điện thoại và đi mua đồ cho mẹ) cho thấy đây là nguyên nhân gốc rễ làm gián đoạn luồng tư duy, dẫn đến sự sụt giảm mức tập trung từ 5/5 xuống 3/5.','Để xử lý yếu tố gây mất tập trung (gọi điện thoại và đi mua đồ cho mẹ), cần thiết lập cơ chế cô lập không gian học tập và thông báo lịch trình cố định với người thân trước khi bắt đầu phiên học.','["Thông báo khung giờ học cố định cho mẹ và yêu cầu không làm phiền trong 2 giờ học tiếp theo.","Di chuyển thiết bị điện thoại ra khỏi khu vực học tập và tắt thông báo trong suốt thời gian học.","Đo lại mức tập trung vào phiên tiếp theo, mục tiêu đạt mức 4/5 để xác nhận hiệu quả của việc cô lập không gian."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì lịch trình hiện tại; nếu mức tập trung vẫn ở mức 3/5 thì thực hiện thay đổi địa điểm học tập sang không gian yên tĩnh hơn.','','2026-04-18 16:50:07','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(80,35,147,'2026-04-19','Fluctuating','["Mức tập trung dao động từ 3/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.67 lần/giờ.","Mức muốn bỏ cuộc duy trì ở 2/5 trong 3 phiên gần nhất, mặc dù mức tập trung có biến động (3/5 → 5/5 → 3/5 → 4/5).","Số giờ học giảm từ 3h ở phiên trước xuống 2h ở phiên kế trước đó, sau đó tăng lên 3h ở phiên hiện tại, cho thấy sự không ổn định trong thời lượng học."]','Nếu Mức tập trung dao động từ 3/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.67 lần/giờ. không thay đổi, Mức muốn bỏ cuộc có khả năng tăng lên 3/5 ở phiên tiếp theo. Nếu thực hiện điều chỉnh thời gian học phù hợp, Mức tập trung có khả năng cải thiện về 4.5/5.','Tín hiệu Mức tập trung dao động từ 3/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.67 lần/giờ. cho thấy sự biến động trong khả năng duy trì sự chú ý, đây là nguyên nhân gốc rễ dẫn đến sự thiếu ổn định trong hiệu suất học tập.','Để xử lý Mức tập trung dao động từ 3/5 ở phiên trước lên 4/5 ở phiên hiện tại, trong khi số lần mất tập trung giảm từ 1.00 lần/giờ xuống 0.67 lần/giờ., cần áp dụng các kỹ thuật quản lý năng lượng cá nhân để giảm thiểu ảnh hưởng của yếu tố buồn ngủ.','["Người học chủ động thực hiện các bài tập vận động nhẹ hoặc thay đổi tư thế trong 5 phút trước mỗi phiên học kéo dài hơn 2 giờ, bắt đầu từ phiên tiếp theo.","Giảm thiểu các yếu tố gây mất tập trung bằng cách tắt thông báo điện thoại và thông báo trên máy tính trong suốt thời gian học của phiên tiếp theo.","Đạt mức tập trung 4/5 và số lần mất tập trung dưới 0.75 lần/giờ trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần xem xét lại thời lượng học. Nếu Mức muốn bỏ cuộc tăng lên 3/5 trong phiên tiếp theo thì cần đánh giá lại yếu tố gây mất tập trung.','','2026-04-18 23:38:33','gemini-2.5-flash-lite','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(81,35,148,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 5/5 xuống 4/5 trong phiên hiện tại, sau khi có 1 phiên giảm đột ngột từ 5/5 xuống 3/5 ở phiên -2.","Mức muốn bỏ cuộc duy trì ở 2/5 trong 3 phiên gần nhất, sau khi có 1 phiên giảm xuống 1/5 ở phiên -3.","Số lần mất tập trung tăng từ 0.67 lần/giờ lên 1.00 lần/giờ trong phiên hiện tại, dù mức tập trung vẫn là 4/5."]','Nếu Mức tập trung giảm từ 5/5 xuống 4/5 trong phiên hiện tại, sau khi có 1 phiên giảm đột ngột từ 5/5 xuống 3/5 ở phiên -2 không thay đổi, khả năng duy trì mức tập trung cao sẽ tiếp tục dao động. Nếu người học chủ động giảm thiểu các yếu tố gây mất tập trung bằng cách thiết lập môi trường học tập yên tĩnh hơn, mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung giảm từ 5/5 xuống 4/5 trong phiên hiện tại, sau khi có 1 phiên giảm đột ngột từ 5/5 xuống 3/5 ở phiên -2 cho thấy sự bất ổn trong khả năng duy trì hiệu suất cao.','Để xử lý sự bất ổn trong khả năng duy trì hiệu suất cao, cần tập trung vào việc ổn định lại mức độ tập trung bằng cách giảm thiểu các yếu tố gây xao nhãng tiềm ẩn.','["Người học sẽ chủ động tắt thông báo các ứng dụng không cần thiết trong 2 giờ học tiếp theo để giảm thiểu gián đoạn.","Kiểm soát môi trường học tập bằng cách chọn không gian yên tĩnh, tránh xa các nguồn tiếng ồn hoặc hoạt động có thể gây xao nhãng trong phiên học tới.","Đạt mức tập trung 5/5 và số lần mất tập trung dưới 0.5 lần/giờ trong phiên học tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược can thiệp. Nếu số lần mất tập trung tăng lên 2 lần/giờ trong phiên tiếp theo thì cần tạm dừng phiên học và nghỉ ngơi.','','2026-04-19 01:02:22','gemini-2.5-flash-lite','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(82,35,149,'2026-04-19','Fluctuating','["Mức tập trung 3/5 ở phiên hiện tại giảm từ 4/5 ở 2 phiên trước đó.","Mức muốn bỏ cuộc 3/5 ở phiên hiện tại tăng từ 2/5 ở 3 phiên trước đó.","Số lần mất tập trung 2 lần (mật độ 1.00 lần/giờ) ở phiên hiện tại tương đương với phiên trước đó (1.00 lần/giờ) nhưng cao hơn phiên trước nữa (0.67 lần/giờ)."]','Nếu Mức muốn bỏ cuộc không thay đổi, Mức tập trung có khả năng giảm xuống dưới 3/5. Nếu giảm số lần mất tập trung xuống dưới 0.5 lần/giờ, Mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức muốn bỏ cuộc 3/5 ở phiên hiện tại tăng từ 2/5 ở 3 phiên trước đó cho thấy sự suy giảm về động lực học tập, có thể ảnh hưởng tiêu cực đến các chỉ số khác.','Để xử lý Mức muốn bỏ cuộc tăng, cần tập trung vào việc tái thiết lập sự hứng thú và mục tiêu học tập rõ ràng hơn cho các phiên tới.','["Người học chủ động xem lại mục tiêu học tập của ngày và tuần, xác định 1-2 nhiệm vụ quan trọng nhất cần hoàn thành trong 1 giờ học tới, bắt đầu từ phiên tiếp theo.","Giảm thiểu các yếu tố gây xao nhãng bằng cách tắt thông báo từ các ứng dụng không liên quan trong 1 giờ học tới.","Trong phiên tiếp theo, Mức muốn bỏ cuộc cần giảm xuống 2/5 hoặc thấp hơn để xác nhận can thiệp có hiệu quả."]','Nếu Mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì cần tạm dừng phiên học. Nếu Mức tập trung giảm xuống 2/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược học tập.','','2026-04-19 01:03:53','gemini-2.5-flash-lite','May');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(83,35,150,'2026-04-19','Stable','["Mức tập trung phiên hiện tại là 5/5, tăng từ 3/5 ở phiên S3 (cùng ngày) và 4/5 ở phiên S2 (cùng ngày).","Mức muốn bỏ cuộc phiên hiện tại là 1/5, giảm từ 3/5 ở phiên S3 (cùng ngày) và 2/5 ở phiên S2 (cùng ngày).","Số lần mất tập trung trong phiên hiện tại là 1 lần (mật độ 0.33 lần/giờ), giảm so với 1.00 lần/giờ ở phiên S3 (cùng ngày) và 1.00 lần/giờ ở phiên S2 (cùng ngày)."]','Nếu Mức tập trung phiên hiện tại là 5/5, tăng từ 3/5 ở phiên S3 (cùng ngày) và 4/5 ở phiên S2 (cùng ngày) không thay đổi, khả năng duy trì hiệu suất học tập cao trong các phiên tới là có thể. Nếu việc giảm số lần mất tập trung xuống 0 lần/giờ được thực hiện, Mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung phiên hiện tại là 5/5, tăng từ 3/5 ở phiên S3 (cùng ngày) và 4/5 ở phiên S2 (cùng ngày) cho thấy sự phục hồi về khả năng duy trì sự chú ý, là yếu tố nền tảng cho việc hoàn thành mục tiêu học tập.','Để xử lý sự phục hồi về khả năng duy trì sự chú ý, cần tập trung vào việc duy trì môi trường học tập ít bị gián đoạn.','["Người học chủ động tắt thông báo các ứng dụng không cần thiết trong 2 giờ đầu của phiên học tiếp theo để giảm thiểu yếu tố gây mất tập trung.","Kiểm soát môi trường học tập bằng cách thông báo cho người thân không làm phiền trong suốt thời gian học của phiên tiếp theo.","Đạt mức tập trung 5/5 và số lần mất tập trung dưới 0.5 lần/giờ trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần xem xét lại các yếu tố gây xao nhãng. Nếu Số lần mất tập trung tăng lên 1 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần đánh giá lại chiến lược can thiệp.','','2026-04-19 01:13:57','gemini-2.5-flash-lite','June');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(84,35,151,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học không đổi (3h).","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên trước lên 2/5 ở phiên hiện tại, dù mục tiêu vẫn đạt được.","Mật độ mất tập trung duy trì ở mức 1.00 lần/giờ trong 3 phiên gần nhất, bao gồm cả phiên hiện tại."]','Nếu mức tập trung tiếp tục dao động quanh 3/5 và mật độ mất tập trung duy trì ở 1.00 lần/giờ, khả năng đạt mục tiêu ở các phiên tới có thể bị ảnh hưởng. Nếu có biện pháp giảm mật độ mất tập trung xuống dưới 0.5 lần/giờ, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung giảm từ 5/5 xuống 3/5 ở phiên hiện tại cho thấy sự bất ổn trong khả năng duy trì hiệu suất học tập, đây là nguyên nhân gốc dẫn đến các biến động khác.','Để xử lý sự bất ổn trong khả năng duy trì hiệu suất học tập, cần tập trung vào việc giảm thiểu các yếu tố gây gián đoạn trong quá trình học.','["Người học chủ động tắt thông báo các ứng dụng không liên quan trong 3 giờ học của phiên tiếp theo để giảm thiểu yếu tố gây mất tập trung.","Người học xác định và ghi lại các yếu tố gây mất tập trung cụ thể (nếu có) trong phiên học tiếp theo để có cơ sở điều chỉnh.","Trong phiên tiếp theo, người học cần đạt mức tập trung tối thiểu 4/5 và giảm mật độ mất tập trung xuống dưới 0.5 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung giảm xuống dưới 3/5 trong phiên tiếp theo thì cần tạm dừng phiên học và đánh giá lại tình hình. Nếu số lần mất tập trung vượt quá 2 lần trong 1 giờ học thì cần áp dụng ngay các biện pháp ngắt quãng ngắn.','','2026-04-19 01:28:23','gemini-2.5-flash-lite','July');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(85,33,152,'2026-04-19','High Risk','["Mức tập trung giảm từ 4/5 ở phiên trước xuống 2/5 trong phiên hiện tại, đồng thời Mức muốn bỏ cuộc tăng từ 2/5 lên 4/5.","Trong phiên hiện tại, có 3 lần mất tập trung với mật độ 1.00 lần/giờ, và Yếu tố gây mất tập trung được xác định là Mệt mỏi.","Mục tiêu không đạt được trong phiên hiện tại, khác với 3 phiên trước đó (phiên -1, -2, -3) đều đạt mục tiêu."]','Nếu Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5 không thay đổi, Mục tiêu có khả năng tiếp tục không đạt được. Nếu một khoảng nghỉ ngơi hợp lý được thực hiện trước phiên học, Mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên trước xuống 2/5 trong phiên hiện tại, đồng thời Mức muốn bỏ cuộc tăng từ 2/5 lên 4/5 cho thấy sự suy giảm nghiêm trọng về khả năng duy trì sự chú ý và ý chí học tập. Đây là nguyên nhân gốc vì nó ảnh hưởng trực tiếp đến hiệu suất và khả năng hoàn thành mục tiêu, không chỉ là một triệu chứng.','Để xử lý Mức tập trung 2/5 và Mức muốn bỏ cuộc 4/5, cần tập trung vào việc giảm thiểu yếu tố Mệt mỏi để cải thiện khả năng duy trì sự chú ý và ý chí học tập.','["Trước phiên học tiếp theo, dành 30 phút để nghỉ ngơi hoàn toàn, không tiếp xúc với thiết bị điện tử.","Trong phiên học tiếp theo, chia nhỏ thời gian học thành các khoảng 45 phút, xen kẽ 5 phút nghỉ giải lao để kiểm soát yếu tố Mệt mỏi.","Trong phiên tiếp theo, Mức tập trung cần đạt ít nhất 3/5 và Mức muốn bỏ cuộc cần giảm xuống 3/5 để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung đạt dưới 3/5 trong phiên tiếp theo thì cần xem xét lại thời lượng và chất lượng giấc ngủ. Nếu Mức muốn bỏ cuộc đạt trên 3/5 trong phiên tiếp theo thì cần đánh giá lại khối lượng công việc.','','2026-04-19 01:34:54','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(86,33,153,'2026-04-19','Fluctuating','["Mức tập trung 3/5 hiện tại tăng từ mức 2/5 ở phiên trước nhưng vẫn thấp hơn mức 4/5 của hai phiên trước đó.","Mật độ mất tập trung duy trì ở mức 1.00 lần/giờ trong hai phiên liên tiếp, không giảm so với phiên trước."]','Nếu mật độ mất tập trung 1.00 lần/giờ không thay đổi, mức tập trung 3/5 có khả năng tiếp tục dao động và không đạt được sự ổn định. Nếu thời gian học được chia nhỏ thành các block 45 phút, mật độ mất tập trung có khả năng giảm về mức 0.5 lần/giờ.','Tín hiệu mật độ mất tập trung 1.00 lần/giờ cho thấy sự thiếu ổn định trong môi trường học tập, là nguyên nhân gốc rễ khiến mức tập trung không thể quay lại ngưỡng 4/5.','Để xử lý mật độ mất tập trung 1.00 lần/giờ, cần áp dụng cơ chế chia nhỏ phiên học thành các block thời gian cố định kèm nghỉ giải lao chủ động để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia 3 giờ học thành 4 block, mỗi block 45 phút, thực hiện trong phiên học tiếp theo.","Loại bỏ các thiết bị điện tử không liên quan khỏi bàn học trong suốt 3 giờ học để kiểm soát mật độ mất tập trung.","Đo lại mật độ mất tập trung vào phiên tiếp theo, mục tiêu đạt mức dưới 0.5 lần/giờ."]','Nếu mật độ mất tập trung đạt mức 1.00 lần/giờ trong phiên tiếp theo thì thực hiện rút ngắn block học xuống 30 phút. Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 45 phút.','','2026-04-19 01:44:58','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(87,33,154,'2026-04-19','Fluctuating','["Mức tập trung dao động từ 4/5 (phiên -3) xuống 2/5 (phiên -2) rồi tăng lên 4/5 (phiên hiện tại), cho thấy sự thiếu ổn định.","Mức muốn bỏ cuộc tăng đột biến từ 2/5 (phiên -3) lên 4/5 (phiên -2) khi mức tập trung giảm xuống 2/5 và mục tiêu không đạt, sau đó trở lại 2/5 ở phiên hiện tại.","Mật độ mất tập trung tăng từ 0.67 lần/giờ (phiên -3) lên 1.00 lần/giờ (phiên -2 và -1) khi mức tập trung giảm, sau đó giảm xuống 0.50 lần/giờ ở phiên hiện tại."]','Nếu sự thiếu ổn định trong khả năng duy trì tập trung không thay đổi, mức tập trung có khả năng tiếp tục dao động và mức muốn bỏ cuộc có thể tăng trở lại 4/5. Nếu việc duy trì mức tập trung ổn định ở 4/5 được thực hiện, mức muốn bỏ cuộc có khả năng cải thiện về 2/5.','Tín hiệu mức tập trung dao động từ 4/5 xuống 2/5 rồi tăng lên 4/5 cho thấy sự thiếu ổn định trong khả năng duy trì tập trung. Đây là nguyên nhân gốc vì sự giảm tập trung trực tiếp dẫn đến việc không đạt mục tiêu và tăng mức muốn bỏ cuộc, không phải là triệu chứng của các yếu tố khác.','Để xử lý sự thiếu ổn định trong khả năng duy trì tập trung, cần thiết lập một cơ chế giúp người học nhận diện và điều chỉnh ngay lập tức khi mức tập trung có dấu hiệu giảm, đặc biệt là khi không có yếu tố gây mất tập trung bên ngoài được ghi nhận.','["Người học tự đặt mục tiêu duy trì mức tập trung ở 4/5 trong 30 phút đầu của phiên học tiếp theo, sử dụng đồng hồ bấm giờ để tự kiểm tra.","Trong phiên học tiếp theo, người học cần chủ động ghi lại bất kỳ dấu hiệu giảm tập trung nào (ví dụ: suy nghĩ lan man, kiểm tra điện thoại) ngay cả khi không có yếu tố gây mất tập trung rõ ràng, để kiểm soát môi trường bên trong.","Ở phiên tiếp theo, mức tập trung cần đạt 4/5 và duy trì ổn định trong ít nhất 3 giờ học để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt dưới 4/5 trong phiên tiếp theo thì cần xem xét lại chiến lược can thiệp. Nếu mức muốn bỏ cuộc đạt trên 2/5 trong phiên tiếp theo thì cần đánh giá lại nguyên nhân gốc.','','2026-04-19 01:46:55','gemini-2.5-flash','May');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(88,33,155,'2026-04-19','High Risk','["Mức tập trung giảm từ 4/5 ở phiên trước xuống 2/5 ở phiên hiện tại, đồng thời số lần mất tập trung tăng từ 0.50 lần/giờ lên 2.00 lần/giờ do yếu tố Mất kết nối mạng internet.","Mức muốn bỏ cuộc tăng đột biến từ 2/5 ở phiên trước lên 5/5 ở phiên hiện tại, cùng với việc không đạt mục tiêu học tập.","Mức tập trung giảm từ 4/5 xuống 2/5 trong khi mức muốn bỏ cuộc tăng từ 2/5 lên 5/5, đảo ngược xu hướng cải thiện của 2 phiên trước (tập trung từ 2/5 lên 4/5, bỏ cuộc từ 4/5 xuống 2/5)."]','Nếu Mất kết nối mạng internet không thay đổi, Mức tập trung có khả năng tiếp tục duy trì ở mức thấp 2/5 hoặc giảm, và Mức muốn bỏ cuộc có khả năng duy trì ở mức 5/5 hoặc tăng. Nếu vấn đề kết nối mạng được khắc phục, Mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên trước xuống 2/5 ở phiên hiện tại, đồng thời số lần mất tập trung tăng từ 0.50 lần/giờ lên 2.00 lần/giờ do yếu tố Mất kết nối mạng internet cho thấy sự gián đoạn từ môi trường học tập là nguyên nhân gốc. Sự cố kết nối mạng trực tiếp gây ra mất tập trung, dẫn đến không đạt mục tiêu và tăng mức muốn bỏ cuộc, chứ không phải là triệu chứng.','Để xử lý Mất kết nối mạng internet, cần tập trung vào việc đảm bảo đường truyền ổn định và loại bỏ các yếu tố gây gián đoạn mạng trong môi trường học tập.','["Trước phiên học tiếp theo, kiểm tra và khắc phục sự cố Mất kết nối mạng internet để đảm bảo đường truyền ổn định trong suốt 2 giờ học.","Trong phiên học tiếp theo, sử dụng thiết bị kết nối mạng dự phòng hoặc di chuyển đến vị trí có tín hiệu mạng mạnh hơn để giảm thiểu số lần mất tập trung do mạng.","Trong phiên học tiếp theo, Mức tập trung cần đạt tối thiểu 4/5 và Số lần mất tập trung cần giảm xuống dưới 0.50 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu Mức tập trung đạt dưới 3/5 trong phiên tiếp theo thì cần rà soát lại toàn bộ hệ thống mạng và thiết bị. Nếu Số lần mất tập trung vẫn trên 1.00 lần/giờ trong phiên tiếp theo thì cần xem xét thay đổi nhà cung cấp dịch vụ internet hoặc phương án kết nối khác.','','2026-04-19 01:52:10','gemini-2.5-flash','June');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(91,33,156,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 4/5 ở phiên -2 xuống 2/5 ở phiên -1 và duy trì 2/5 ở phiên hiện tại, trong khi số giờ học tăng từ 2h lên 5h.","Mật độ mất tập trung tăng từ 0.50 lần/giờ ở phiên -2 lên 2.00 lần/giờ ở phiên -1, sau đó giảm xuống 1.00 lần/giờ ở phiên hiện tại.","Mức muốn bỏ cuộc dao động mạnh, từ 2/5 ở phiên -2 lên 5/5 ở phiên -1, sau đó giảm xuống 2/5 ở phiên hiện tại."]','Nếu mức tập trung 2/5 không thay đổi, mật độ mất tập trung có khả năng duy trì ở mức cao hoặc tăng lên khi số giờ học tăng. Nếu thời lượng học được điều chỉnh phù hợp với khả năng tập trung hiện tại, mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên -2 xuống 2/5 ở phiên -1 và duy trì 2/5 ở phiên hiện tại, trong khi số giờ học tăng từ 2h lên 5h cho thấy sự suy giảm khả năng duy trì tập trung khi thời lượng học tăng lên. Đây là nguyên nhân gốc vì khả năng tập trung thấp ảnh hưởng trực tiếp đến hiệu suất học tập và có thể dẫn đến các triệu chứng khác như tăng mật độ mất tập trung.','Để xử lý sự suy giảm khả năng duy trì tập trung khi thời lượng học tăng lên, cần điều chỉnh thời lượng học để phù hợp với ngưỡng tập trung hiện tại của người học, sau đó tăng dần thời lượng học một cách có kiểm soát.','["Trong phiên tiếp theo, người học sẽ giới hạn thời lượng học tối đa là 3 giờ để phù hợp với mức tập trung 2/5 hiện tại.","Trong phiên tiếp theo, người học sẽ chia nhỏ thời gian học thành các khoảng 30-45 phút và nghỉ ngắn giữa các khoảng để kiểm soát môi trường học tập và giảm mật độ mất tập trung.","Trong phiên tiếp theo, mức tập trung cần đạt 3/5 và mật độ mất tập trung cần giảm xuống dưới 0.7 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung vẫn ở 2/5 trong phiên tiếp theo thì cần xem xét lại thời lượng học và các yếu tố môi trường. Nếu mật độ mất tập trung tăng lên trên 1.00 lần/giờ trong phiên tiếp theo thì cần đánh giá lại chiến lược chia nhỏ thời gian học.','','2026-04-19 03:35:52','gemini-2.5-flash','June');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(94,32,159,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên -2 xuống 4/5 ở phiên hiện tại, trong khi mật độ mất tập trung tăng từ 0.40 lần/giờ lên 0.67 lần/giờ.","Mật độ mất tập trung ở phiên hiện tại (0.67 lần/giờ) cao hơn so với phiên -2 (0.40 lần/giờ) mặc dù không ghi nhận yếu tố gây mất tập trung cụ thể.","Mức tập trung dao động giữa 3/5 và 5/5 trong 3 phiên gần nhất (3/5 ở phiên -3, 5/5 ở phiên -2, 4/5 ở phiên -1 và phiên hiện tại)."]','Nếu sự suy giảm trong khả năng duy trì tập trung không thay đổi, mức tập trung có khả năng tiếp tục dao động hoặc giảm xuống dưới 4/5 trong các phiên tiếp theo. Nếu việc chủ động kiểm soát môi trường học tập được thực hiện, mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung giảm từ 5/5 ở phiên -2 xuống 4/5 ở phiên hiện tại, trong khi mật độ mất tập trung tăng từ 0.40 lần/giờ lên 0.67 lần/giờ cho thấy sự suy giảm trong khả năng duy trì tập trung. Đây là nguyên nhân gốc vì nó trực tiếp phản ánh hiệu suất học tập và có thể dẫn đến các hệ quả tiêu cực khác, không phải là triệu chứng của một vấn đề khác.','Để xử lý sự suy giảm trong khả năng duy trì tập trung, cần thiết lập một cơ chế chủ động kiểm soát môi trường học tập để giảm thiểu các yếu tố tiềm ẩn gây mất tập trung, ngay cả khi chúng không được ghi nhận rõ ràng.','["Trước phiên học tiếp theo, người học sẽ dành 5 phút để loại bỏ mọi vật dụng không liên quan đến việc học khỏi khu vực làm việc.","Trong phiên học tiếp theo, người học sẽ đặt điện thoại ở chế độ im lặng và úp xuống, cách xa tầm với để tránh bị phân tâm bởi thông báo.","Ở phiên tiếp theo, mức tập trung cần đạt 5/5 và mật độ mất tập trung cần giảm xuống dưới 0.40 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt dưới 4/5 trong phiên tiếp theo thì cần xem xét lại chiến lược can thiệp. Nếu mật độ mất tập trung đạt trên 0.67 lần/giờ trong phiên tiếp theo thì cần đánh giá lại các yếu tố môi trường.','','2026-04-19 03:43:16','gemini-2.5-flash','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(96,32,160,'2026-04-19','High Risk','["Mức muốn bỏ cuộc tăng đột biến từ 1/5 ở phiên trước lên 5/5 ở phiên hiện tại, trong khi mức tập trung duy trì ở 4/5.","Mật độ mất tập trung ở phiên hiện tại là 1.50 lần/giờ, cao hơn đáng kể so với 0.67 lần/giờ ở phiên trước, mặc dù mức tập trung không đổi.","Yếu tố gây mất tập trung xuất hiện 2 lần trong phiên hiện tại, cùng với mức muốn bỏ cuộc tăng từ 1/5 lên 5/5."]','Nếu mức muốn bỏ cuộc 5/5 không thay đổi, mức tập trung 4/5 có khả năng giảm xuống dưới 3/5 trong phiên tiếp theo. Nếu hành động giảm yếu tố gây mất tập trung được thực hiện, mức muốn bỏ cuộc có khả năng cải thiện về mức 1/5.','Tín hiệu Mức muốn bỏ cuộc tăng đột biến từ 1/5 ở phiên trước lên 5/5 ở phiên hiện tại, trong khi mức tập trung duy trì ở 4/5 cho thấy đây là nguyên nhân gốc. Mức muốn bỏ cuộc cao đột biến có thể là yếu tố nội tại ảnh hưởng đến sự duy trì nỗ lực, ngay cả khi khả năng tập trung vẫn còn, và có thể dẫn đến việc giảm hiệu suất hoặc ngừng học trong các phiên tiếp theo.','Để xử lý mức muốn bỏ cuộc 5/5, cần tập trung vào việc giảm thiểu các yếu tố gây mất tập trung đã được ghi nhận, nhằm tạo ra một môi trường học tập ít xao nhãng hơn, từ đó gián tiếp tác động tích cực đến cảm giác muốn duy trì và hoàn thành mục tiêu.','["Trong phiên tiếp theo, người học sẽ dành 5 phút đầu tiên để xác định và loại bỏ 2 yếu tố gây mất tập trung đã ghi nhận.","Trong suốt phiên học tiếp theo, người học sẽ chủ động ghi lại bất kỳ yếu tố gây mất tập trung nào xuất hiện để có thể xử lý ngay lập tức.","Mức muốn bỏ cuộc cần đạt 1/5 và số lần mất tập trung cần giảm xuống dưới 1 lần/giờ trong phiên tiếp theo để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 4/5 hoặc cao hơn trong phiên tiếp theo thì cần xem xét lại chiến lược can thiệp. Nếu số lần mất tập trung đạt 2 lần hoặc cao hơn trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung.','','2026-04-19 03:43:37','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(98,32,166,'2026-04-19','High Risk','["Mức tập trung giảm từ 4/5 ở phiên -1 xuống 1/5 ở phiên hiện tại, đồng thời mật độ mất tập trung tăng từ 2.00 lần/giờ lên 40.00 lần/giờ.","Mức muốn bỏ cuộc tăng đột biến từ 2/5 ở phiên -1 lên 5/5 ở phiên hiện tại, sau khi đã giảm liên tục trong 3 phiên trước đó (từ 3/5 xuống 2/5).","Mặc dù không ghi nhận Yếu tố gây mất tập trung cụ thể, số lần mất tập trung là 10 lần trong 0.25 giờ học, dẫn đến việc không đạt mục tiêu học tập."]','Nếu mức tập trung 1/5 và mật độ mất tập trung 40.00 lần/giờ không thay đổi, mức muốn bỏ cuộc 5/5 có khả năng duy trì hoặc tăng, và mục tiêu học tập sẽ tiếp tục không đạt. Nếu thời gian học được điều chỉnh phù hợp với khả năng duy trì tập trung, mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên -1 xuống 1/5 ở phiên hiện tại, đồng thời mật độ mất tập trung tăng từ 2.00 lần/giờ lên 40.00 lần/giờ cho thấy sự suy giảm nghiêm trọng về khả năng duy trì sự chú ý, đây là nguyên nhân gốc dẫn đến các hệ quả khác.','Để xử lý sự suy giảm nghiêm trọng về khả năng duy trì sự chú ý, cần tập trung vào việc điều chỉnh thời lượng học để phù hợp với ngưỡng tập trung hiện tại, nhằm giảm mật độ mất tập trung và cải thiện chất lượng phiên học.','["Giới hạn thời gian học của phiên tiếp theo xuống còn 0.15 giờ để phù hợp với mức tập trung 1/5 hiện tại.","Trong phiên tiếp theo, loại bỏ mọi yếu tố có thể gây mất tập trung trong môi trường học tập để giảm số lần mất tập trung.","Trong phiên tiếp theo, mức tập trung cần đạt ít nhất 3/5 và mật độ mất tập trung cần giảm xuống dưới 10 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt dưới 2/5 trong phiên tiếp theo thì cần xem xét lại thời lượng học và môi trường. Nếu mật độ mất tập trung vượt quá 15 lần/giờ trong phiên tiếp theo thì cần tạm dừng phiên học để đánh giá lại nguyên nhân.','','2026-04-19 04:08:42','gemini-2.5-flash','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(99,18,169,'2026-04-19','Stable','["Mật độ mất tập trung duy trì ở mức 1.00 lần/giờ trong 3 phiên liên tiếp dù số giờ học dao động từ 2h đến 3h.","Mức tập trung ổn định ở 3/5 trong 5 phiên gần nhất đi kèm với mức muốn bỏ cuộc không đổi ở 2/5."]','Nếu mật độ mất tập trung 1.00 lần/giờ không thay đổi, mức tập trung 3/5 có khả năng tiếp tục duy trì mà không có sự đột phá. Nếu thời gian học mỗi phiên được chia nhỏ thành các block 45 phút, mật độ mất tập trung có khả năng giảm xuống dưới 0.50 lần/giờ.','Tín hiệu mật độ mất tập trung duy trì ở mức 1.00 lần/giờ cho thấy đây là rào cản kỹ thuật cố định làm giới hạn khả năng đạt mức tập trung cao hơn 3/5.','Để xử lý mật độ mất tập trung 1.00 lần/giờ, cần áp dụng cơ chế chia nhỏ thời gian học thành các block cố định để giảm tải áp lực duy trì sự chú ý liên tục.','["Chia nhỏ thời gian học thành các block 45 phút học tập trung và 5 phút nghỉ ngơi trong 48 giờ tới.","Loại bỏ các thiết bị điện tử không liên quan khỏi bàn học trong mỗi block 45 phút để kiểm soát mật độ mất tập trung.","Đo lại mật độ mất tập trung vào phiên tiếp theo, mục tiêu đạt mức dưới 0.50 lần/giờ để xác nhận hiệu quả."]','Nếu mật độ mất tập trung đạt mức 1.00 lần/giờ trong phiên tiếp theo thì thực hiện giảm thời gian mỗi block học xuống 30 phút. Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì duy trì cấu trúc block 45 phút.','','2026-04-19 04:20:59','gemini-3.1-flash-lite-preview','March');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(100,36,175,'2026-04-19','Stable','["Mức tập trung đạt 4/5 trong phiên học 2 giờ, nhưng có 2 lần mất tập trung do tiếng ồn, tương đương mật độ 1.00 lần/giờ.","Mặc dù có 2 lần mất tập trung do tiếng ồn, mục tiêu học tập vẫn được đạt và mức muốn bỏ cuộc là 2/5."]','Nếu tiếng ồn không được kiểm soát, số lần mất tập trung có khả năng duy trì ở mức 1.00 lần/giờ hoặc tăng lên. Nếu môi trường học tập được cách ly khỏi tiếng ồn, mức tập trung có khả năng cải thiện về 5/5.','Tín hiệu Mức tập trung đạt 4/5 trong phiên học 2 giờ, nhưng có 2 lần mất tập trung do tiếng ồn, tương đương mật độ 1.00 lần/giờ cho thấy tiếng ồn là nguyên nhân trực tiếp gây ra các sự kiện mất tập trung, ảnh hưởng đến chất lượng tập trung dù mục tiêu vẫn đạt được.','Để xử lý tiếng ồn gây mất tập trung, cần thiết lập một môi trường học tập yên tĩnh hơn bằng cách giảm thiểu hoặc loại bỏ nguồn tiếng ồn.','["Người học sẽ tìm một không gian học tập yên tĩnh hơn hoặc sử dụng tai nghe chống ồn trong phiên học tiếp theo.","Trước khi bắt đầu phiên học tiếp theo, người học sẽ kiểm tra và đảm bảo không có nguồn tiếng ồn lớn trong môi trường xung quanh.","Trong phiên học tiếp theo, số lần mất tập trung cần đạt 0 lần để xác nhận can thiệp có hiệu quả."]','Nếu số lần mất tập trung đạt 1 lần hoặc hơn trong phiên tiếp theo thì cần đánh giá lại môi trường học tập. Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần xem xét lại các yếu tố gây xao nhãng khác.','','2026-04-19 06:03:51','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(101,36,176,'2026-04-19','Stable','["Mức tập trung duy trì ở 4/5 trong cả hai phiên gần nhất.","Mức muốn bỏ cuộc duy trì ở 2/5 trong cả hai phiên gần nhất.","Mật độ mất tập trung giảm từ 1.00 lần/giờ ở phiên trước xuống 0.67 lần/giờ ở phiên hiện tại, không có yếu tố gây mất tập trung được ghi nhận."]','Nếu mật độ mất tập trung tiếp tục duy trì ở mức thấp 0.67 lần/giờ, mức tập trung có khả năng duy trì ở 4/5. Nếu môi trường học tập tiếp tục không có yếu tố gây mất tập trung, mật độ mất tập trung có khả năng cải thiện về dưới 0.5 lần/giờ.','Tín hiệu mật độ mất tập trung giảm từ 1.00 lần/giờ xuống 0.67 lần/giờ cho thấy khả năng duy trì sự tập trung đã được cải thiện, đây là nguyên nhân gốc giúp duy trì mức tập trung cao và mức muốn bỏ cuộc thấp.','Để xử lý mật độ mất tập trung, cần duy trì các điều kiện môi trường không có yếu tố gây mất tập trung để hỗ trợ sự tập trung liên tục.','["Trong phiên học tiếp theo, người học sẽ chủ động kiểm tra và loại bỏ mọi yếu tố có khả năng gây mất tập trung trước khi bắt đầu phiên học.","Trong phiên học tiếp theo, người học sẽ thực hiện một phiên học kéo dài 3 giờ để kiểm tra khả năng duy trì mật độ mất tập trung ở mức thấp.","Trong phiên học tiếp theo, mật độ mất tập trung cần đạt dưới 0.67 lần/giờ để xác nhận can thiệp có hiệu quả."]','Nếu mật độ mất tập trung đạt 0.67 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần xem xét lại các yếu tố môi trường. Nếu mức tập trung giảm xuống dưới 4/5 trong phiên tiếp theo thì cần đánh giá lại chiến lược duy trì sự tập trung.','','2026-04-19 06:05:03','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(102,36,177,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học duy trì 3h.","Mật độ mất tập trung duy trì 0.67 lần/giờ ở phiên hiện tại, tương đương phiên trước, nhưng mức tập trung giảm 1 bậc.","Mức muốn bỏ cuộc duy trì 2/5 qua cả 3 phiên, không thay đổi."]','Nếu mức tập trung tiếp tục giảm trong cùng số giờ học, mức tập trung có khả năng giảm xuống dưới 3/5. Nếu thời lượng học được điều chỉnh phù hợp với khả năng duy trì tập trung, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên trước xuống 3/5 ở phiên hiện tại, trong khi số giờ học duy trì 3h cho thấy sự suy giảm khả năng duy trì sự chú ý trong cùng khoảng thời gian học. Đây là nguyên nhân gốc vì nó ảnh hưởng trực tiếp đến chất lượng học tập, không phải là triệu chứng của một vấn đề khác.','Để xử lý sự suy giảm khả năng duy trì sự chú ý trong cùng khoảng thời gian học, cần điều chỉnh thời lượng học để phù hợp với mức tập trung hiện tại, nhằm tối ưu hóa hiệu quả học tập.','["Trong phiên tiếp theo, giảm số giờ học xuống 2 giờ để phù hợp với mức tập trung hiện tại.","Trong phiên tiếp theo, chia nhỏ thời gian học thành các khoảng ngắn hơn (ví dụ: 45 phút học, 15 phút nghỉ) để kiểm soát môi trường học tập và giảm khả năng mất tập trung.","Trong phiên tiếp theo, mức tập trung cần đạt 4/5 với số giờ học đã điều chỉnh để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt 3/5 hoặc thấp hơn trong phiên tiếp theo thì cần xem xét lại thời lượng và cấu trúc phiên học. Nếu số lần mất tập trung tăng lên 1 lần/giờ hoặc cao hơn trong phiên tiếp theo thì cần đánh giá lại các yếu tố gây mất tập trung.','','2026-04-19 06:07:51','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(103,32,168,'2026-04-19','Fluctuating','["Mức tập trung dao động mạnh từ 4/5 (phiên -3) xuống 1/5 (phiên -2) rồi tăng lên 5/5 (phiên -1) và hiện tại là 3/5.","Mật độ mất tập trung tăng đột biến từ 2.00 lần/giờ (phiên -3) lên 40.00 lần/giờ (phiên -2) khi mức tập trung giảm xuống 1/5, sau đó giảm về 0.00 lần/giờ (phiên -1) và hiện tại là 1.00 lần/giờ.","Mức muốn bỏ cuộc tăng từ 2/5 (phiên -3) lên 5/5 (phiên -2) khi mục tiêu không đạt, sau đó giảm về 1/5 (phiên -1) và hiện tại là 2/5."]','Nếu sự dao động của mức tập trung không thay đổi, mật độ mất tập trung có khả năng tiếp tục biến động mạnh và ảnh hưởng đến việc đạt mục tiêu. Nếu một cơ chế giúp ổn định mức tập trung được thực hiện, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu Mức tập trung dao động mạnh từ 4/5 (phiên -3) xuống 1/5 (phiên -2) rồi tăng lên 5/5 (phiên -1) và hiện tại là 3/5 cho thấy sự thiếu ổn định trong khả năng duy trì tập trung. Đây là nguyên nhân gốc vì nó ảnh hưởng trực tiếp đến mật độ mất tập trung và khả năng đạt mục tiêu, từ đó tác động đến mức muốn bỏ cuộc.','Để xử lý sự dao động mạnh của mức tập trung, cần thiết lập một quy trình khởi động phiên học giúp người học chuẩn bị tinh thần và môi trường, nhằm giảm thiểu các yếu tố gây xao nhãng tiềm ẩn ngay từ đầu phiên.','["Trước phiên học tiếp theo, dành 5 phút để thực hiện quy trình khởi động phiên học, bao gồm việc dọn dẹp không gian học tập và tắt thông báo điện thoại.","Trong phiên học tiếp theo, ghi lại cụ thể các yếu tố gây mất tập trung (nếu có) để xác định nguyên nhân cụ thể ảnh hưởng đến mức tập trung.","Ở phiên tiếp theo, mức tập trung cần đạt tối thiểu 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung dưới 3/5 trong phiên tiếp theo thì cần xem xét lại quy trình khởi động phiên học. Nếu mật độ mất tập trung trên 1.00 lần/giờ trong phiên tiếp theo thì cần phân tích sâu hơn các yếu tố gây xao nhãng.','','2026-04-19 06:10:08','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(104,32,178,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 5/5 ở phiên -2 xuống 3/5 ở phiên hiện tại, trong khi số giờ học tăng từ 0.25h lên 2h.","Mật độ mất tập trung tăng từ 0.00 lần/giờ ở phiên -2 lên 0.50 lần/giờ ở phiên hiện tại, tương ứng với mức tập trung giảm.","Mức muốn bỏ cuộc duy trì ở 2/5 trong phiên hiện tại, sau khi đã giảm từ 5/5 ở phiên -3 xuống 1/5 ở phiên -2 và tăng lên 2/5 ở phiên -1."]','Nếu khả năng duy trì tập trung khi thời lượng học tăng lên không thay đổi, mức tập trung có khả năng tiếp tục ở mức 3/5 hoặc thấp hơn trong các phiên học dài. Nếu thời lượng học được điều chỉnh phù hợp với khả năng duy trì tập trung, mức tập trung có khả năng cải thiện về mức 5/5.','Tín hiệu Mức tập trung giảm từ 5/5 ở phiên -2 xuống 3/5 ở phiên hiện tại, trong khi số giờ học tăng từ 0.25h lên 2h cho thấy sự suy giảm khả năng duy trì tập trung khi thời lượng học tăng lên. Đây là nguyên nhân gốc vì khả năng duy trì tập trung kém sẽ ảnh hưởng trực tiếp đến hiệu suất học tập trong các phiên dài hơn, không phải là triệu chứng.','Để xử lý sự suy giảm khả năng duy trì tập trung khi thời lượng học tăng lên, cần điều chỉnh thời lượng học để phù hợp với ngưỡng tập trung hiện tại, sau đó tăng dần thời lượng học một cách có kiểm soát.','["Trong phiên tiếp theo, giới hạn thời lượng học xuống 0.25h để tối ưu hóa mức tập trung.","Trong phiên tiếp theo, theo dõi số lần mất tập trung để đảm bảo mật độ mất tập trung duy trì ở 0.00 lần/giờ.","Trong phiên tiếp theo, mức tập trung cần đạt 5/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt 5/5 trong phiên tiếp theo thì tăng thời lượng học lên 0.5h ở phiên kế tiếp. Nếu mật độ mất tập trung lớn hơn 0.00 lần/giờ trong phiên tiếp theo thì giữ nguyên thời lượng học 0.25h ở phiên kế tiếp.','','2026-04-19 06:10:30','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(108,36,180,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 4/5 ở phiên -2 xuống 3/5 ở phiên hiện tại, trong khi số lần mất tập trung là 2 lần với yếu tố Điện thoại.","Mức muốn bỏ cuộc tăng từ 2/5 ở phiên -1 lên 3/5 ở phiên hiện tại.","Mật độ mất tập trung giảm từ 0.67 lần/giờ ở phiên -1 xuống 0.40 lần/giờ ở phiên hiện tại, nhưng yếu tố gây mất tập trung vẫn là Điện thoại."]','Nếu yếu tố Điện thoại tiếp tục gây mất tập trung, mức tập trung có khả năng duy trì ở mức 3/5 hoặc thấp hơn. Nếu hành động kiểm soát yếu tố Điện thoại được thực hiện, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu Mức tập trung giảm từ 4/5 ở phiên -2 xuống 3/5 ở phiên hiện tại, trong khi số lần mất tập trung là 2 lần với yếu tố Điện thoại cho thấy sự suy giảm khả năng duy trì tập trung do yếu tố gây xao nhãng cụ thể. Đây là nguyên nhân gốc vì việc mất tập trung trực tiếp ảnh hưởng đến chất lượng học tập và có thể dẫn đến các hệ quả khác như tăng mức muốn bỏ cuộc.','Để xử lý yếu tố Điện thoại gây mất tập trung, cần thiết lập một cơ chế chủ động loại bỏ hoặc giảm thiểu sự tiếp cận với điện thoại trong suốt thời gian học.','["Đặt điện thoại ở chế độ im lặng và để xa tầm với (ví dụ: phòng khác) trong 5 giờ học tiếp theo.","Sử dụng ứng dụng chặn thông báo hoặc chế độ không làm phiền trên điện thoại trong suốt phiên học tiếp theo để giảm thiểu kích thích từ yếu tố Điện thoại.","Đo lại mức tập trung và số lần mất tập trung do Điện thoại trong phiên tiếp theo, mục tiêu là mức tập trung đạt 4/5 và số lần mất tập trung do Điện thoại là 0."]','Nếu mức tập trung đạt 3/5 hoặc thấp hơn trong phiên tiếp theo thì cần xem xét lại vị trí đặt điện thoại và thời gian sử dụng. Nếu số lần mất tập trung do Điện thoại lớn hơn 0 trong phiên tiếp theo thì cần áp dụng biện pháp chặn truy cập điện thoại cứng rắn hơn.','','2026-04-19 06:15:45','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(109,32,179,'2026-04-19','Fluctuating','["Mức tập trung duy trì ở 3/5 trong 3 phiên gần nhất (S10, S11, S12) sau khi đạt 5/5 ở phiên S9.","Mục tiêu không đạt ở phiên hiện tại (S12) trong khi 3 phiên trước đó (S9, S10, S11) đều đạt mục tiêu.","Số giờ học giảm từ 2h ở phiên S10 và S11 xuống còn 0.5h ở phiên hiện tại (S12) trong khi mức tập trung vẫn giữ ở 3/5."]','Nếu mức tập trung duy trì ở 3/5 không thay đổi, mục tiêu có khả năng tiếp tục không đạt và số giờ học có thể tiếp tục giảm. Nếu thời gian học được điều chỉnh phù hợp với mức tập trung hiện tại, mục tiêu đạt được có khả năng cải thiện.','Tín hiệu Mức tập trung duy trì ở 3/5 trong 3 phiên gần nhất (S10, S11, S12) sau khi đạt 5/5 ở phiên S9 cho thấy sự ổn định ở mức tập trung trung bình, điều này có thể là nguyên nhân gốc dẫn đến việc không đạt mục tiêu và giảm thời gian học.','Để xử lý mức tập trung duy trì ở 3/5, cần điều chỉnh thời lượng phiên học để phù hợp với khả năng duy trì tập trung hiện tại, nhằm tăng khả năng hoàn thành mục tiêu.','["Thiết lập mục tiêu học tập cho phiên tiếp theo với thời lượng tối đa 0.5 giờ để phù hợp với mức tập trung 3/5 hiện tại.","Đảm bảo môi trường học tập không có yếu tố gây mất tập trung trong phiên tiếp theo để duy trì mức tập trung 3/5.","Đo lại mức tập trung và trạng thái đạt mục tiêu ở phiên tiếp theo, mục tiêu là đạt mục tiêu với mức tập trung không dưới 3/5."]','Nếu mức tập trung đạt 4/5 trong phiên tiếp theo thì xem xét tăng thời lượng học. Nếu mục tiêu không đạt trong phiên tiếp theo thì cần đánh giá lại độ khó của mục tiêu và thời lượng học.','','2026-04-19 06:50:44','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(110,32,181,'2026-04-19','Fluctuating','["Mức tập trung duy trì ở 3/5 trong 4 phiên liên tiếp (S10, S11, S12, S13) sau khi dao động từ 1/5 lên 5/5 ở các phiên trước đó (S8, S9).","Số giờ học giảm từ 2h ở phiên S11 xuống 0.5h ở phiên S12 và tiếp tục giảm xuống 0.25h ở phiên hiện tại S13, trong khi mục tiêu không đạt ở cả hai phiên S12 và S13.","Mức muốn bỏ cuộc giảm từ 2/5 ở phiên S11 xuống 1/5 ở phiên S12 và duy trì 1/5 ở phiên hiện tại S13, đồng thời số lần mất tập trung là 0 ở cả hai phiên S12 và S13."]','Nếu số giờ học tiếp tục giảm hoặc duy trì ở mức thấp như 0.25h, mục tiêu có khả năng tiếp tục không đạt trong các phiên tiếp theo. Nếu thời lượng học tập được tăng lên ít nhất 0.5h, khả năng đạt mục tiêu có thể cải thiện.','Tín hiệu số giờ học giảm từ 2h ở phiên S11 xuống 0.5h ở phiên S12 và tiếp tục giảm xuống 0.25h ở phiên hiện tại S13, trong khi mục tiêu không đạt ở cả hai phiên S12 và S13 cho thấy sự giảm sút đáng kể về thời lượng học tập và khả năng hoàn thành mục tiêu. Đây là nguyên nhân gốc vì thời lượng học tập ngắn có thể trực tiếp dẫn đến việc không đạt mục tiêu, ngay cả khi mức tập trung không thay đổi.','Để xử lý việc số giờ học giảm và không đạt mục tiêu, cần tập trung vào việc thiết lập và duy trì thời lượng học tập tối thiểu cho mỗi phiên.','["Thiết lập mục tiêu thời lượng học tập tối thiểu 0.5h cho phiên tiếp theo.","Trước khi bắt đầu phiên học tiếp theo, chuẩn bị môi trường học tập để đảm bảo không có yếu tố gây gián đoạn trong ít nhất 0.5h.","Trong phiên tiếp theo, cần đạt được ít nhất 0.5h học tập và hoàn thành mục tiêu đã đặt ra để xác nhận hiệu quả can thiệp."]','Nếu số giờ học trong phiên tiếp theo dưới 0.5h thì cần xem xét lại mục tiêu thời lượng học tập. Nếu mục tiêu không đạt trong phiên tiếp theo thì cần đánh giá lại chiến lược thiết lập mục tiêu.','','2026-04-19 06:55:35','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(111,18,174,'2026-04-19','Fluctuating','["Mức tập trung giảm từ 4/5 ở phiên -1 xuống 3/5 ở phiên hiện tại, đồng thời mật độ mất tập trung tăng từ 0.75 lần/giờ lên 0.67 lần/giờ (tức số lần mất tập trung tăng từ 3 lên 2 trong khi giờ học giảm từ 4h xuống 3h).","Mức muốn bỏ cuộc tăng từ 2/5 ở phiên -1 lên 3/5 ở phiên hiện tại, sau khi đã giảm từ 3/5 xuống 1/5 ở phiên -2.","Yếu tố gây mất tập trung là xem tivi xuất hiện 2 lần trong phiên hiện tại, góp phần vào mức tập trung 3/5."]','Nếu yếu tố gây mất tập trung là xem tivi không được kiểm soát, mức tập trung có khả năng tiếp tục duy trì ở mức 3/5 hoặc thấp hơn. Nếu hành động loại bỏ yếu tố xem tivi được thực hiện, mức tập trung có khả năng cải thiện về mức 4/5.','Tín hiệu Yếu tố gây mất tập trung là xem tivi xuất hiện 2 lần trong phiên hiện tại, góp phần vào mức tập trung 3/5 cho thấy sự hiện diện của yếu tố gây xao nhãng trực tiếp là nguyên nhân gốc dẫn đến giảm mức tập trung và tăng mật độ mất tập trung.','Để xử lý yếu tố gây mất tập trung là xem tivi, cần thiết lập một môi trường học tập không có sự hiện diện của thiết bị phát tivi hoặc đảm bảo thiết bị không hoạt động trong suốt thời gian học.','["Trong phiên học tiếp theo, đảm bảo tivi trong khu vực học tập được tắt hoàn toàn hoặc di chuyển ra khỏi tầm nhìn trong suốt 3 giờ học.","Trước khi bắt đầu phiên học tiếp theo, kiểm tra và xác nhận không có thiết bị phát tivi nào đang hoạt động hoặc có thể gây xao nhãng trong môi trường học.","Trong phiên học tiếp theo, mức tập trung cần đạt 4/5 và số lần mất tập trung cần giảm xuống 1 lần hoặc ít hơn để xác nhận can thiệp có hiệu quả."]','Nếu mức tập trung đạt 3/5 hoặc thấp hơn trong phiên tiếp theo thì cần xem xét lại vị trí học và các yếu tố gây xao nhãng khác. Nếu số lần mất tập trung đạt 2 lần hoặc nhiều hơn trong phiên tiếp theo thì cần đánh giá lại hiệu quả của việc loại bỏ yếu tố xem tivi.','','2026-04-19 06:58:25','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(112,32,183,'2026-04-19','High Risk','["Mức tập trung giảm từ 3/5 ở phiên trước xuống 2/5 ở phiên hiện tại, trong khi mức muốn bỏ cuộc tăng từ 1/5 lên 4/5.","Mức tập trung có xu hướng giảm liên tục từ 3/5 (phiên -3) xuống 2/5 (phiên hiện tại) trong 4 phiên gần nhất, đồng thời mức muốn bỏ cuộc tăng từ 2/5 (phiên -3) lên 4/5 (phiên hiện tại).","Mục tiêu không đạt trong 3 phiên liên tiếp (phiên -2, -1 và hiện tại), trùng với giai đoạn mức tập trung duy trì ở 3/5 rồi giảm xuống 2/5."]','Nếu mức tập trung 2/5 không thay đổi, mục tiêu có khả năng tiếp tục không đạt và mức muốn bỏ cuộc có khả năng duy trì ở 4/5 hoặc cao hơn. Nếu thời lượng học được điều chỉnh phù hợp với khả năng tập trung, mức tập trung có khả năng cải thiện về 3/5.','Tín hiệu Mức tập trung giảm từ 3/5 ở phiên trước xuống 2/5 ở phiên hiện tại, trong khi mức muốn bỏ cuộc tăng từ 1/5 lên 4/5 cho thấy sự suy giảm nghiêm trọng về khả năng duy trì sự chú ý, dẫn đến cảm giác muốn từ bỏ. Đây là nguyên nhân gốc vì mức tập trung thấp trực tiếp ảnh hưởng đến hiệu suất và ý chí tiếp tục.','Để xử lý sự suy giảm mức tập trung, cần điều chỉnh thời lượng học để phù hợp với khả năng duy trì sự chú ý hiện tại, giúp người học hoàn thành mục tiêu trong khoảng thời gian ngắn hơn.','["Trong phiên tiếp theo, người học sẽ bắt đầu với thời lượng học tối đa 30 phút để tập trung hoàn thành một mục tiêu cụ thể.","Trước khi bắt đầu phiên học tiếp theo, người học sẽ chuẩn bị môi trường học không có yếu tố gây xao nhãng để tối ưu hóa sự tập trung trong thời gian ngắn.","Trong phiên tiếp theo, mức tập trung cần đạt ít nhất 3/5 và mục tiêu cần được hoàn thành để xác nhận hiệu quả của việc điều chỉnh thời lượng học."]','Nếu mức tập trung đạt 3/5 trong phiên tiếp theo thì tiếp tục duy trì thời lượng học ngắn và tăng dần. Nếu mức muốn bỏ cuộc đạt 4/5 trong phiên tiếp theo thì cần xem xét lại mục tiêu học tập và thời lượng học.','','2026-04-19 06:59:16','gemini-2.5-flash','April');
INSERT INTO "analysis_reports" ("id","user_id","entry_id","report_date","risk_level","key_signals","short_term_forecast","primary_risk_driver","intervention_strategy","action_plan_48h","monitoring_protocol","raw_ai_response","created_at","analyzed_by","key_name") VALUES(113,18,182,'2026-04-19','Fluctuating','["Mức tập trung duy trì ở 3/5 trong phiên hiện tại, không thay đổi so với phiên trước (3/5) và thấp hơn mức 4/5 của phiên -2.","Mức muốn bỏ cuộc tăng từ 1/5 ở phiên -3 lên 3/5 ở phiên hiện tại, duy trì mức 3/5 trong 2 phiên gần nhất.","Số lần mất tập trung là 2 lần với mật độ 0.67 lần/giờ trong phiên hiện tại, tương đương với phiên trước và thấp hơn mật độ 1.00 lần/giờ ở phiên -3, với yếu tố gây mất tập trung là ồn ào."]','Nếu mức muốn bỏ cuộc duy trì ở 3/5, mức tập trung có khả năng tiếp tục ở 3/5 hoặc giảm xuống. Nếu một hành động cụ thể được thực hiện để giảm yếu tố gây mất tập trung là ồn ào, mức tập trung có khả năng cải thiện về 4/5.','Tín hiệu Mức muốn bỏ cuộc tăng từ 1/5 ở phiên -3 lên 3/5 ở phiên hiện tại, duy trì mức 3/5 trong 2 phiên gần nhất cho thấy đây là nguyên nhân gốc. Mức muốn bỏ cuộc tăng lên có thể ảnh hưởng đến khả năng duy trì tập trung và hiệu suất học tập, trong khi mức tập trung thấp hoặc yếu tố gây mất tập trung có thể là triệu chứng của sự thiếu động lực hoặc khả năng chịu đựng kém hơn.','Để xử lý mức muốn bỏ cuộc duy trì ở 3/5, cần tập trung vào việc giảm thiểu các yếu tố môi trường gây khó chịu, cụ thể là ồn ào, để tạo điều kiện thuận lợi hơn cho việc duy trì sự tập trung và từ đó gián tiếp tác động tích cực đến mức muốn bỏ cuộc.','["Trong phiên tiếp theo, người học sẽ chủ động tìm một không gian học tập yên tĩnh hơn hoặc sử dụng nút bịt tai để giảm thiểu yếu tố ồn ào trong suốt 3 giờ học.","Trước khi bắt đầu phiên học tiếp theo, người học sẽ kiểm tra và đảm bảo môi trường xung quanh không có nguồn gây ồn ào lớn trong phạm vi nghe thấy.","Trong phiên tiếp theo, mức muốn bỏ cuộc cần đạt 2/5 hoặc thấp hơn, và mức tập trung cần đạt 4/5 để xác nhận can thiệp có hiệu quả."]','Nếu mức muốn bỏ cuộc đạt 3/5 hoặc cao hơn trong phiên tiếp theo thì cần đánh giá lại chiến lược can thiệp. Nếu mức tập trung đạt 3/5 hoặc thấp hơn trong phiên tiếp theo thì cần xem xét các yếu tố gây mất tập trung khác ngoài ồn ào.','','2026-04-19 06:59:35','gemini-2.5-flash','April');
