PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE d1_migrations(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  full_name TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, role TEXT DEFAULT 'user', is_locked INTEGER DEFAULT 0, locked_at DATETIME, locked_reason TEXT, must_change_password INTEGER DEFAULT 0, temp_password TEXT);
CREATE TABLE IF NOT EXISTS "analysis_reports" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER REFERENCES users(id),
  entry_id INTEGER REFERENCES daily_entries(id),
  report_date DATE DEFAULT CURRENT_DATE,
  risk_level TEXT CHECK(risk_level IN ('Stable','Fluctuating','High Risk')),
  key_signals TEXT,
  short_term_forecast TEXT,
  primary_risk_driver TEXT,
  intervention_strategy TEXT,
  action_plan_48h TEXT,
  monitoring_protocol TEXT,
  raw_ai_response TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, analyzed_by TEXT, key_name TEXT);
CREATE TABLE IF NOT EXISTS "daily_entries" (
  id                  INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id             INTEGER REFERENCES users(id),
  session_date        DATE    DEFAULT CURRENT_DATE,
  session_number      INTEGER DEFAULT 1,
  session_time        TEXT,
  study_hours         REAL,
  focus_level         INTEGER CHECK(focus_level BETWEEN 1 AND 5),
  distraction_count   INTEGER,
  distracting_factors TEXT,
  goal_achieved       INTEGER CHECK(goal_achieved IN (0,1)),
  emotional_state     TEXT,
  dropout_feeling     INTEGER CHECK(dropout_feeling BETWEEN 1 AND 5),
  created_at          DATETIME DEFAULT CURRENT_TIMESTAMP, is_active INTEGER DEFAULT 1, deactivated_at DATETIME, deactivated_by TEXT, deactivated_reason TEXT,
  UNIQUE(user_id, session_date, session_number)
);
CREATE TABLE model_config (
  id           INTEGER PRIMARY KEY AUTOINCREMENT,
  model_name   TEXT    NOT NULL UNIQUE,   
  display_name TEXT    NOT NULL,          
  sort_order   INTEGER NOT NULL DEFAULT 0,
  enabled      INTEGER NOT NULL DEFAULT 1,
  timeout_ms   INTEGER NOT NULL DEFAULT 20000, 
  daily_limit  INTEGER,                   
  notes        TEXT,                      
  updated_at   DATETIME DEFAULT CURRENT_TIMESTAMP,
  updated_by   TEXT                       
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_reports_user     ON analysis_reports(user_id, created_at);
CREATE INDEX idx_reports_entry_id ON analysis_reports(entry_id);
CREATE INDEX idx_entries_user_date    ON daily_entries(user_id, session_date);
CREATE INDEX idx_entries_session_date ON daily_entries(session_date);
CREATE INDEX idx_entries_user_session ON daily_entries(user_id, session_date, session_number);
CREATE UNIQUE INDEX idx_users_email_unique
  ON users (LOWER(email));
CREATE INDEX idx_users_role             ON users(role);
CREATE INDEX idx_users_email            ON users(email);
CREATE INDEX idx_daily_entries_user_id  ON daily_entries(user_id);
CREATE INDEX idx_daily_entries_date     ON daily_entries(session_date);
CREATE INDEX idx_daily_entries_active   ON daily_entries(is_active);
CREATE INDEX idx_ai_reports_user_id     ON analysis_reports(user_id);
CREATE INDEX idx_ai_reports_entry_id    ON analysis_reports(entry_id);
